/* ============================================================================
   LIFE — the 2026 audit's §6 database gaps, as new profile sections
   ----------------------------------------------------------------------------
   Every default character used to get a wound, a fear, a lie, a defence and a
   ghost, and no section at all for what they can DO, what they are actually
   trying to get done this month, what went right in their life, how they mend
   things, what their contradictions are for, or how their role changes with the
   room. The tool "needs positive origins, ordinary satisfactions, and chosen
   commitments as first-class ways of explaining behaviour" — these are those.

   Seven sections. Each is registered in PROFILE_SECTIONS (engine.js) so it gets
   a toggle, a type selector, a weight, a sheet group and export support for
   free; the ones marked defaultOn:false there ship switched off so a default
   sheet does not grow by twenty cards.

     Competence & Method      what they can do, HOW they think about doing it,
                              and the limitation that comes with it
     Positive Origins         what went right — trust learned, care that held,
                              a success that was ordinary, a conflict repaired
     Goals & Stakes           (draws one of each) the immediate objective, the
                              longer aim, and the price / the competing claim
     Ordinary Texture         preferences, routines, affiliations, a thing
                              practised badly — texture without a rare slot
     Recovery & Repair        what they do AFTER conflict; feeds the pressure
                              chain's aftermath step
     Contradiction Functions  what the contradiction is FOR — protective
                              hypocrisy, aspirational values, exceptions,
                              detachment, strategic politeness, concealment
     Role by Context          (draws one of each) the seat they take among
                              peers, under authority, and with dependents —
                              instead of one universal seat in every room

   Deliberately first packets, not complete pools: the audit says to start with
   a few categories and compare output before expanding the schema across the
   bank. tests/bank-report.js reports these as thin until they are grown.
   Ids 170001+.
   ========================================================================== */
const TRAITS_LIFE = [
// ================================================================ COMPETENCE & METHOD
// ---- Hands & Materials
{id:170001,section:"Competence & Method",category:"Hands & Materials",trait:"Can fix anything with a motor",desc:"Engines, pumps, fans — takes them apart by feel and puts them back working; cannot explain any of it in words.",example:"(listens to it for a second) Bearing. Left side. Give me an hour.",intensity:4,rarity:"distinctive",pol:{intel:-1,disc:1},conceptFamily:"competence-mechanical",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170002,section:"Competence & Method",category:"Hands & Materials",trait:"Cooks for forty without a recipe",desc:"Feeds a crowd from whatever is there; a single portion for one person defeats them.",example:"(the pot is the size of a bath; the result is perfect; there is no leftover plan)",intensity:3,rarity:"uncommon",pol:{warm:1},conceptFamily:"competence-cooking",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170003,section:"Competence & Method",category:"Hands & Materials",trait:"Grows things anywhere",desc:"Windowsills, verges, a tin — something is always coming up; keeps nothing indoors alive past a fortnight.",example:"(the balcony is a farm. The houseplant is a memory.)",intensity:2,rarity:"common",pol:{},conceptFamily:"competence-growing",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170004,section:"Competence & Method",category:"Hands & Materials",trait:"Sews, mends, alters — never from a pattern",desc:"Clothes come out fitted and sound from eye and hand alone; a printed pattern makes them clumsy.",example:"Turn round. (pins) Done. — You didn't measure. — I looked.",intensity:3,rarity:"distinctive",pol:{intel:-1},conceptFamily:"competence-sewing",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170005,section:"Competence & Method",category:"Hands & Materials",trait:"Strong back, careful hands",desc:"Lifts, carries and builds all day and handles the fragile part of any job with unexpected tenderness.",example:"(the piano moved. The vase, carried separately, on a cushion.)",intensity:3,rarity:"common",pol:{act:1},conceptFamily:"competence-labour",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170006,section:"Competence & Method",category:"Hands & Materials",trait:"Can drive anything",desc:"Cars, vans, tractors, the boat once — competent within minutes; hopeless at giving directions to anyone else.",example:"I'll drive. — Do you know the way? — No. I'll drive though.",intensity:3,rarity:"uncommon",pol:{},conceptFamily:"competence-driving",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170007,section:"Competence & Method",category:"Hands & Materials",trait:"Reads a building by walking through it",desc:"Knows where the damp is, which wall is load-bearing and what the roof will do next winter, from one visit.",example:"That corner's going to go. Two years. Maybe three if you fix the gutter.",intensity:4,rarity:"signature",pol:{intel:1},conceptFamily:"competence-building",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170008,section:"Competence & Method",category:"Hands & Materials",trait:"Good with animals, bad with their owners",desc:"Any frightened creature settles under their hands; the humans attached to it get short shrift.",example:"(the dog is calm in thirty seconds. The owner is told to be quiet.)",intensity:3,rarity:"distinctive",pol:{warm:1,man:-1},conceptFamily:"competence-animals",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170009,section:"Competence & Method",category:"Hands & Materials",trait:"Slow, and never has to redo it",desc:"Takes twice as long as anyone else on a practical job and is the only one whose work still holds ten years on.",example:"(the shelf from 2011 has not moved. The three faster shelves have.)",intensity:3,rarity:"uncommon",pol:{disc:1,act:-1},conceptFamily:"competence-durable",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170010,section:"Competence & Method",category:"Hands & Materials",trait:"First aid without fuss",desc:"Stops bleeding, splints, calms — quietly, correctly — and is squeamish about nothing except dentists.",example:"Keep your hand there. Higher. Good. You're fine. Talk to me about the match.",intensity:4,rarity:"distinctive",pol:{disc:1,emo:-1},conceptFamily:"competence-firstaid",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170011,section:"Competence & Method",category:"Hands & Materials",trait:"Makes do with what's in the drawer",desc:"Improvises a working solution from string, tape and a spoon; will not, ever, go and buy the right part.",example:"(the hinge is a bent fork and has been for six years)",intensity:2,rarity:"common",pol:{intel:-1,rebel:1},conceptFamily:"competence-improvise",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170012,section:"Competence & Method",category:"Hands & Materials",trait:"Knots, loads, lashings",desc:"Anything that needs tying, securing or hauled is done right first time; indoors, cannot wrap a present.",example:"(the load will not shift on any road. The birthday gift is mostly tape.)",intensity:2,rarity:"uncommon",pol:{},conceptFamily:"competence-rigging",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170013,section:"Competence & Method",category:"Hands & Materials",trait:"Precise to the millimetre, blind to the whole",desc:"Every joint perfect, every edge true — and the finished piece is sometimes the wrong size for the room.",example:"It's beautiful. — Thank you. — It doesn't fit through the door.",intensity:4,rarity:"distinctive",pol:{disc:1},conceptFamily:"competence-precision",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170014,section:"Competence & Method",category:"Hands & Materials",trait:"Can't cook, can bake",desc:"Dinner is a disaster; bread, cakes and pastry are exact and excellent. It's the measuring.",example:"(the stew is inedible. The loaf beside it won a prize.)",intensity:2,rarity:"uncommon",pol:{disc:1},conceptFamily:"competence-baking",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170015,section:"Competence & Method",category:"Hands & Materials",trait:"Hands that remember what the mind forgot",desc:"Skills learned decades ago return in the fingers the moment the tool is picked up, to their own surprise.",example:"I haven't done this since I was nineteen. (does it perfectly.)",intensity:3,rarity:"signature",pol:{},conceptFamily:"competence-memory",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170016,section:"Competence & Method",category:"Hands & Materials",trait:"Handy, and unsafe about it",desc:"Gets the job done quickly and well with no regard for ladders, gloves or the mains.",example:"(fixed the light. Was standing on the sink. Live.)",intensity:4,rarity:"common",pol:{disc:-1,rebel:1},conceptFamily:"competence-unsafe",behaviorFunction:"provide",reviewStatus:"reviewed"},

// ---- People & Rooms
{id:170017,section:"Competence & Method",category:"People & Rooms",trait:"Knows who's about to cry",desc:"Reads a room's emotional weather a minute ahead of everyone else; is often wrong about their own.",example:"(quietly moves the tissues within reach; ninety seconds later, needed)",intensity:3,rarity:"distinctive",pol:{emo:1,intel:-1},conceptFamily:"competence-emotional-read",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170018,section:"Competence & Method",category:"People & Rooms",trait:"Can make a stranger talk",desc:"Gets a life story out of anyone in ten minutes and could not name what they did to get it.",example:"(the taxi driver has told them about his divorce. It's been four streets.)",intensity:3,rarity:"uncommon",pol:{warm:1},conceptFamily:"competence-elicit",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170019,section:"Competence & Method",category:"People & Rooms",trait:"Seats a difficult table",desc:"Puts the right people next to each other and the wrong ones far apart, instinctively; the event goes well and nobody knows why.",example:"(the feuding cousins are three seats apart, with the deaf uncle between)",intensity:2,rarity:"uncommon",pol:{intel:1},conceptFamily:"competence-hosting",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170020,section:"Competence & Method",category:"People & Rooms",trait:"Negotiates for others, never for self",desc:"Gets a good deal for anyone they represent and takes the first offer on their own behalf.",example:"(got the client double. Accepted their own pay cut without a word.)",intensity:3,rarity:"distinctive",pol:{asrt:1,ego:-1},conceptFamily:"competence-negotiate",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170021,section:"Competence & Method",category:"People & Rooms",trait:"Hears the lie, not the liar",desc:"Detects the false note in any account and is often wrong about which person it came from.",example:"Something in that's not right. — Which bit? — Don't know. Something.",intensity:3,rarity:"distinctive",pol:{hon:1},conceptFamily:"competence-lie-detect",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170022,section:"Competence & Method",category:"People & Rooms",trait:"Calms a crowd with a voice",desc:"A tone that settles a panicking room; useless one-to-one, where the same voice reads as distant.",example:"(the hall goes quiet. Later, alone with a friend: 'You sound like a tannoy.')",intensity:4,rarity:"signature",pol:{asrt:1},conceptFamily:"competence-crowd",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170023,section:"Competence & Method",category:"People & Rooms",trait:"Remembers everyone's children's names",desc:"A practical social memory that opens every door — and no memory at all for what was agreed in the meeting.",example:"How's Priya's exam? — (the deal terms from Tuesday are gone)",intensity:2,rarity:"common",pol:{warm:1},conceptFamily:"competence-social-memory",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170024,section:"Competence & Method",category:"People & Rooms",trait:"Teaches the slow learner",desc:"Endlessly patient with anyone struggling to understand; sharp with anyone who understands and won't try.",example:"(the fourth explanation, gentler than the first. Then, to the clever one: 'Stop wasting my time.')",intensity:3,rarity:"uncommon",pol:{warm:1,agr:-1},conceptFamily:"competence-teach",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170025,section:"Competence & Method",category:"People & Rooms",trait:"Knows when to leave a room",desc:"Reads the moment a presence stops helping and goes, without ceremony; cannot tell when to arrive.",example:"(gone before the argument turned. Turned up two hours early for the party.)",intensity:2,rarity:"distinctive",pol:{},conceptFamily:"competence-timing",behaviorFunction:"avoid",reviewStatus:"reviewed"},
{id:170026,section:"Competence & Method",category:"People & Rooms",trait:"Talks anyone down off anything",desc:"Ledges, rages, resignations — has a gift for the crisis conversation and no gift at all for the ordinary one.",example:"(saved the marriage at midnight. Can't do small talk at breakfast.)",intensity:4,rarity:"signature",pol:{warm:1,emo:1},conceptFamily:"competence-crisis-talk",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170027,section:"Competence & Method",category:"People & Rooms",trait:"Finds the one person who can help",desc:"In any organisation, locates the clerk, nurse or foreman who actually makes things happen, within a day.",example:"Don't talk to the manager. Talk to Dee. Dee's on Thursdays.",intensity:3,rarity:"distinctive",pol:{intel:1},conceptFamily:"competence-find-helper",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170028,section:"Competence & Method",category:"People & Rooms",trait:"Says the hard thing kindly",desc:"Delivers bad news, criticism or a refusal so that people thank them; is bad at delivering good news, which comes out flat.",example:"(the redundancy conversation ended with a hug. The promotion was announced like a weather report.)",intensity:3,rarity:"uncommon",pol:{warm:1,hon:1},conceptFamily:"competence-hard-news",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170029,section:"Competence & Method",category:"People & Rooms",trait:"Makes children behave, somehow",desc:"Every child in range does what they ask, once, quietly; adults are entirely unmanageable.",example:"(the toddler stops screaming. The father keeps arguing.)",intensity:3,rarity:"uncommon",pol:{asrt:1},conceptFamily:"competence-children",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170030,section:"Competence & Method",category:"People & Rooms",trait:"Reads a room, misreads a person",desc:"Groups are transparent to them — moods, alliances, who's leaving; any single individual is a mystery.",example:"The room wants to stop. — And him? — I have no idea what he wants.",intensity:2,rarity:"distinctive",pol:{intel:1},conceptFamily:"competence-group-read",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170031,section:"Competence & Method",category:"People & Rooms",trait:"Charm that works once",desc:"Wins anyone over on first meeting; the second meeting is where it always comes apart.",example:"(everyone loved them at the interview. Month two is different.)",intensity:3,rarity:"common",pol:{warm:1,hon:-1},conceptFamily:"competence-first-impression",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170032,section:"Competence & Method",category:"People & Rooms",trait:"Holds a grudge for someone else",desc:"Remembers every slight done to their people and prosecutes it, years on, in ways the injured party has forgotten.",example:"He still owes your sister an apology. — She's forgotten. — I haven't.",intensity:2,rarity:"uncommon",pol:{warm:1,agr:-1},conceptFamily:"competence-loyalty-memory",behaviorFunction:"protect",reviewStatus:"reviewed"},

// ---- Systems & Logistics
{id:170033,section:"Competence & Method",category:"Systems & Logistics",trait:"Runs the household like a depot",desc:"Stocks, rotas, timings — nothing runs out and nobody is ever late; cannot bear anyone else touching the system.",example:"(the freezer is labelled and dated. Touch nothing.)",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"competence-household",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170034,section:"Competence & Method",category:"Systems & Logistics",trait:"Sees the bottleneck from the door",desc:"Walks into any process and knows where it's jammed; is tactless about saying so.",example:"It's the sign-off. It's always the sign-off. Who's doing sign-off?",intensity:4,rarity:"distinctive",pol:{intel:1,man:-1},conceptFamily:"competence-bottleneck",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170035,section:"Competence & Method",category:"Systems & Logistics",trait:"Plans the journey to the minute",desc:"Connections, contingencies, snacks — travel with them is flawless; unplanned days make them frantic.",example:"(the itinerary has a column for 'if it rains'. There is no column for 'what shall we do?')",intensity:3,rarity:"uncommon",pol:{disc:1},conceptFamily:"competence-travel",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170036,section:"Competence & Method",category:"Systems & Logistics",trait:"Keeps the books, hates the money",desc:"Accounts to the penny, always balanced; visibly uncomfortable talking about what any of it is for.",example:"(the ledger is perfect. Asked about the budget, changes the subject.)",intensity:2,rarity:"uncommon",pol:{disc:1,emo:-1},conceptFamily:"competence-accounts",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170037,section:"Competence & Method",category:"Systems & Logistics",trait:"The one who knows where everything is",desc:"Any object, document or person can be located in seconds — from a system that exists only in their head.",example:"Blue folder, third shelf, behind the kettle. — Why behind the kettle? — It's where it goes.",intensity:3,rarity:"distinctive",pol:{},conceptFamily:"competence-locate",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170038,section:"Competence & Method",category:"Systems & Logistics",trait:"Queues, forms, offices — a natural",desc:"Bureaucracy holds no fear; gets the permit, the refund, the appointment that nobody else could.",example:"(three hours, four counters, one stamp. Emerged with the thing.)",intensity:2,rarity:"common",pol:{disc:1},conceptFamily:"competence-bureaucracy",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170039,section:"Competence & Method",category:"Systems & Logistics",trait:"Delegates well and checks nothing",desc:"Hands work to exactly the right person and then never follows up, on principle.",example:"You've got it. — Do you want to see— — No. You've got it.",intensity:3,rarity:"distinctive",pol:{ego:1,disc:-1},conceptFamily:"competence-delegate",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170040,section:"Competence & Method",category:"Systems & Logistics",trait:"Lists as a way of life",desc:"Everything is written down, crossed off and re-listed; a task not on a list does not, functionally, exist.",example:"(you asked on the stairs. It wasn't written down. It didn't happen.)",intensity:2,rarity:"common",pol:{disc:1},conceptFamily:"competence-lists",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170041,section:"Competence & Method",category:"Systems & Logistics",trait:"Rescues the failing project, then leaves",desc:"Brilliant at the turnaround and bored by the running; every success is handed to someone else at the finish.",example:"(it's working. So: they've resigned.)",intensity:4,rarity:"signature",pol:{intel:1,cur:1},conceptFamily:"competence-turnaround",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170042,section:"Competence & Method",category:"Systems & Logistics",trait:"Keeps twelve people fed and moving",desc:"A camp, a crew, a family holiday — logistics for a group come naturally; alone, they forget to eat.",example:"(everyone else had breakfast. They had a coffee, standing, at eleven.)",intensity:3,rarity:"uncommon",pol:{warm:1,disc:1},conceptFamily:"competence-group-logistics",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170043,section:"Competence & Method",category:"Systems & Logistics",trait:"Reads a contract in a glance",desc:"Finds the clause that matters on page nine in seconds; cannot read a novel to the end.",example:"Clause 14b. That's the one they'll use. — You've had it ten seconds.",intensity:4,rarity:"distinctive",pol:{intel:1},conceptFamily:"competence-contract",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170044,section:"Competence & Method",category:"Systems & Logistics",trait:"A timetable in the head",desc:"Knows, without looking, what time the bus, the tide, the shift change and the post are — for the whole district.",example:"The 42's late. — How do you— — It's late.",intensity:2,rarity:"uncommon",pol:{},conceptFamily:"competence-timetable",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170045,section:"Competence & Method",category:"Systems & Logistics",trait:"Organises other people's chaos",desc:"Sorts anyone else's desk, life or business into order; their own is a permanent avalanche.",example:"(the client's office is transformed. Their own car has a nest in it.)",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"competence-others-chaos",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170046,section:"Competence & Method",category:"Systems & Logistics",trait:"Thinks in flowcharts, speaks in fragments",desc:"Sees the whole system at once and can only ever describe one box of it at a time.",example:"So this goes — no, first this — actually, it's all — hang on, I'll draw it.",intensity:3,rarity:"distinctive",pol:{intel:1,vol:-1},conceptFamily:"competence-flowchart",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170047,section:"Competence & Method",category:"Systems & Logistics",trait:"Never loses a receipt, always loses the keys",desc:"Paper trails immaculate to the decade; physical objects vanish hourly.",example:"(the 2009 tax return, instantly. The car keys: a search party.)",intensity:2,rarity:"common",pol:{},conceptFamily:"competence-receipts",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170048,section:"Competence & Method",category:"Systems & Logistics",trait:"Can run the place, won't be seen to",desc:"Quietly keeps the whole operation going from a junior post, and refuses every title offered.",example:"(the manager is on leave. Nothing changed. Nothing ever changes when the manager is on leave.)",intensity:4,rarity:"signature",pol:{disc:1,ego:-1},conceptFamily:"competence-shadow-runner",behaviorFunction:"provide",reviewStatus:"reviewed"},

// ---- Craft & Knowledge
{id:170049,section:"Competence & Method",category:"Craft & Knowledge",trait:"Draws what they can't say",desc:"Any explanation ends up as a sketch, and the sketch is always clearer than the words were.",example:"(the napkin now has the whole plan on it, and it's right)",intensity:3,rarity:"distinctive",pol:{intel:1,vol:-1},conceptFamily:"craft-drawing",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170050,section:"Competence & Method",category:"Craft & Knowledge",trait:"Knows every bird by its call",desc:"A deep, specific expertise in one corner of the world, carried lightly and shared only if asked.",example:"(pauses mid-sentence) Wren. Sorry. Go on.",intensity:2,rarity:"uncommon",pol:{cur:1},conceptFamily:"craft-naturalist",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170051,section:"Competence & Method",category:"Craft & Knowledge",trait:"Plays one instrument properly",desc:"Genuinely good on one thing, learned young and kept up; refuses every request to perform.",example:"(the piano in the corner is theirs. Nobody has heard it in company.)",intensity:3,rarity:"uncommon",pol:{ego:-1},conceptFamily:"craft-music",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170052,section:"Competence & Method",category:"Craft & Knowledge",trait:"Writes a clean sentence, slowly",desc:"Everything they put down is exact and readable; it takes them all day, and they will not be hurried.",example:"(the two-paragraph letter took the morning. Every word earns its place.)",intensity:3,rarity:"distinctive",pol:{disc:1,act:-1},conceptFamily:"craft-writing",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170053,section:"Competence & Method",category:"Craft & Knowledge",trait:"Remembers every date, forgets every name",desc:"A calendar-perfect memory for when things happened, attached to no idea who was there.",example:"March the fourth, 1998. — Who with? — Someone. It was a Wednesday.",intensity:2,rarity:"common",pol:{},conceptFamily:"craft-dates",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170054,section:"Competence & Method",category:"Craft & Knowledge",trait:"The one who read the manual",desc:"Actually knows how the thing works — the camera, the boiler, the law — and is asked about it constantly.",example:"(the family's technical support, unpaid, for twenty years)",intensity:3,rarity:"common",pol:{intel:1,disc:1},conceptFamily:"craft-manual",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170055,section:"Competence & Method",category:"Craft & Knowledge",trait:"Tells a story that lands",desc:"Can hold a table for ten minutes with an anecdote and land the ending; cannot answer a direct question in under five.",example:"(the story about the goat. Every time. It still works.)",intensity:3,rarity:"uncommon",pol:{vol:1,warm:1},conceptFamily:"craft-storytelling",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170056,section:"Competence & Method",category:"Craft & Knowledge",trait:"Speaks three languages, badly and bravely",desc:"Wades into any tongue with enthusiasm and errors, and gets understood through sheer nerve.",example:"(the grammar is wrong in three languages. The bread was bought anyway.)",intensity:3,rarity:"distinctive",pol:{cur:1,ego:1},conceptFamily:"craft-languages",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170057,section:"Competence & Method",category:"Craft & Knowledge",trait:"Sings in tune, only when nobody's listening",desc:"A true, unshowy voice heard through walls and never in a room with anyone else in it.",example:"(the kitchen, alone, the radio off: quite lovely. The door opens: silence.)",intensity:2,rarity:"uncommon",pol:{ego:-1},conceptFamily:"craft-singing",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170058,section:"Competence & Method",category:"Craft & Knowledge",trait:"Knows the history of every street",desc:"Local, specific, encyclopaedic memory of place — who lived where, what burned, what was built over.",example:"That was the bakery. Before that, the chapel. Before that, a pond.",intensity:3,rarity:"distinctive",pol:{cur:1},conceptFamily:"craft-local-history",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170059,section:"Competence & Method",category:"Craft & Knowledge",trait:"Expert in one thing, humble about the rest",desc:"Genuine authority on a narrow subject, and openly, cheerfully ignorant of everything adjacent.",example:"Ask me about beetles. Not moths. I don't know anything about moths.",intensity:3,rarity:"uncommon",pol:{hon:1,ego:1},conceptFamily:"craft-narrow-expert",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170060,section:"Competence & Method",category:"Craft & Knowledge",trait:"Does the crossword in ink",desc:"Words, puzzles, codes — a quick and exact verbal mind; arithmetic defeats them entirely.",example:"(fourteen down in seconds. The bill split needs a calculator.)",intensity:2,rarity:"common",pol:{intel:1},conceptFamily:"craft-verbal",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170061,section:"Competence & Method",category:"Craft & Knowledge",trait:"Photographic for faces",desc:"Never forgets a face, however brief the meeting; cannot remember what was said to it.",example:"Ferry, 2004, you had a red bag. — What did we talk about? — No idea.",intensity:3,rarity:"distinctive",pol:{},conceptFamily:"craft-faces",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170062,section:"Competence & Method",category:"Craft & Knowledge",trait:"A trade learned at fourteen",desc:"Something skilled and physical, mastered young, that still pays the bills and shapes the hands.",example:"(forty years on the same tools. The hands are the CV.)",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"craft-trade",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170063,section:"Competence & Method",category:"Craft & Knowledge",trait:"Self-taught and gapped",desc:"Deep knowledge with strange holes where the textbook chapters would have been.",example:"(can derive the theorem. Has never heard the word for it.)",intensity:3,rarity:"distinctive",pol:{cur:1,rebel:1},conceptFamily:"craft-self-taught",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170064,section:"Competence & Method",category:"Craft & Knowledge",trait:"Brilliant, and cannot be taught",desc:"Extraordinary ability in one field and a complete inability to take instruction in it from anyone.",example:"(the best in the county. Has left every teacher within a month.)",intensity:5,rarity:"signature",pol:{intel:1,rebel:1,agr:-1},conceptFamily:"craft-unteachable",behaviorFunction:"perform",reviewStatus:"reviewed"},

// ================================================================ POSITIVE ORIGINS & MAINTENANCE
// ---- Learned Trust
{id:170065,section:"Positive Origins",category:"Learned Trust",trait:"Someone kept every promise",desc:"One adult in childhood who never once said a thing they didn't do; the baseline expectation of people was set there.",example:"She said Friday. It was always Friday. So I assume Friday.",intensity:3,rarity:"distinctive",pol:{warm:1,hon:1},conceptFamily:"origin-promises-kept",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170066,section:"Positive Origins",category:"Learned Trust",trait:"Was believed the first time",desc:"Told a hard truth young and was taken at their word, immediately; still expects to be.",example:"I said what happened. They believed me. That's — that's just how it goes, isn't it?",intensity:3,rarity:"uncommon",pol:{hon:1,ego:1},conceptFamily:"origin-believed",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170067,section:"Positive Origins",category:"Learned Trust",trait:"Grew up with an open door",desc:"A childhood house where anyone could come in and be fed; assumes rooms are welcoming until shown otherwise.",example:"(walks into the stranger's kitchen and puts the kettle on)",intensity:2,rarity:"common",pol:{warm:1},conceptFamily:"origin-open-door",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170068,section:"Positive Origins",category:"Learned Trust",trait:"Lent money and got it back",desc:"Early experience of trust rewarded, repeatedly; treats people as reliable and is rarely disappointed, and shrugs when they are.",example:"He'll pay it back. — And if he doesn't? — Then I'll know something. Cheap, for knowing.",intensity:2,rarity:"uncommon",pol:{warm:1,pos:1},conceptFamily:"origin-lending",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170069,section:"Positive Origins",category:"Learned Trust",trait:"Told the secret, and it was kept",desc:"Confided something enormous once and it went no further; the world has been safer to speak in since.",example:"(said it at fifteen. Nobody has ever mentioned it. So: people can be trusted.)",intensity:3,rarity:"distinctive",pol:{emo:1,warm:1},conceptFamily:"origin-secret-kept",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170070,section:"Positive Origins",category:"Learned Trust",trait:"A stranger was kind at the worst moment",desc:"One unlooked-for act of help from someone with nothing to gain; has passed it on ever since.",example:"A woman at the station paid the fare. Never got her name. I pay fares now.",intensity:3,rarity:"uncommon",pol:{warm:1,pos:1},conceptFamily:"origin-stranger-kindness",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170071,section:"Positive Origins",category:"Learned Trust",trait:"The team that had their back",desc:"A crew, a unit, a kitchen — once part of something that covered for each other without being asked.",example:"(assumes the person beside them will step in. Usually they do; it's catching.)",intensity:3,rarity:"common",pol:{warm:1,agr:1},conceptFamily:"origin-team",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170072,section:"Positive Origins",category:"Learned Trust",trait:"Trusts slowly, then entirely",desc:"Learned early that trust is built in instalments; once it's there, it does not get audited.",example:"Took three years. Now I'd give her the house keys and not think about it.",intensity:3,rarity:"distinctive",pol:{warm:1,disc:1},conceptFamily:"origin-slow-trust",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170073,section:"Positive Origins",category:"Learned Trust",trait:"Was forgiven, once, when it mattered",desc:"Did something unforgivable young and was forgiven anyway; has never quite believed in permanent verdicts since.",example:"I should have lost him for it. I didn't. I try to be that for people.",intensity:4,rarity:"signature",pol:{warm:1,agr:1},conceptFamily:"origin-forgiven",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170074,section:"Positive Origins",category:"Learned Trust",trait:"A door was left unlocked for them",desc:"Someone made a standing offer — a bed, a job, a phone number — that was never withdrawn; safety has a shape.",example:"'Any time' meant any time. I tested it at three in the morning. Still meant it.",intensity:3,rarity:"uncommon",pol:{warm:1},conceptFamily:"origin-standing-offer",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170075,section:"Positive Origins",category:"Learned Trust",trait:"Adults who admitted they were wrong",desc:"Grew up hearing grown-ups apologise; finds the ordinary refusal to do so genuinely strange.",example:"Why won't he just say sorry? It's not hard. My dad did it all the time.",intensity:2,rarity:"uncommon",pol:{hon:1,agr:1},conceptFamily:"origin-adults-apologised",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170076,section:"Positive Origins",category:"Learned Trust",trait:"Told they were enough, and believed it",desc:"A plain, repeated childhood message that they didn't have to earn their place; carries it lightly.",example:"(doesn't perform. Doesn't seem to need to. Has never needed to.)",intensity:3,rarity:"distinctive",pol:{ego:1,pos:1},conceptFamily:"origin-enough",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170077,section:"Positive Origins",category:"Learned Trust",trait:"A neighbourhood that watched out",desc:"Raised somewhere every adult was, in a small way, responsible for every child; still expects a village.",example:"(leaves the pram outside the shop and is startled to be told not to)",intensity:2,rarity:"common",pol:{warm:1,agr:1},conceptFamily:"origin-village",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170078,section:"Positive Origins",category:"Learned Trust",trait:"Trusted with the keys at twelve",desc:"Given real responsibility early and rose to it; assumes people will, given the same.",example:"Let her do it. — She's fourteen. — I was twelve. Let her do it.",intensity:3,rarity:"uncommon",pol:{ego:1,disc:1},conceptFamily:"origin-trusted-young",behaviorFunction:"provide",reviewStatus:"reviewed"},

// ---- Stable Care
{id:170079,section:"Positive Origins",category:"Stable Care",trait:"The same breakfast every day of childhood",desc:"An unbroken small ritual — the porridge, the radio, the walk — that made the world feel held.",example:"(still makes it. Still at seven. Still the radio.)",intensity:2,rarity:"common",pol:{disc:1,pos:1},conceptFamily:"origin-ritual",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170080,section:"Positive Origins",category:"Stable Care",trait:"Nobody ever left in anger",desc:"A house where arguments ended in the same room they started in; walking out is unthinkable to them.",example:"You don't leave. You finish it. Then you have tea.",intensity:3,rarity:"distinctive",pol:{warm:1,agr:1},conceptFamily:"origin-no-walkout",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170081,section:"Positive Origins",category:"Stable Care",trait:"A grandparent with time",desc:"One older person who was never in a hurry and always had a chair beside them; patience was learned by being shown it.",example:"(sits with the child for an hour, doing nothing much, exactly as it was done for them)",intensity:3,rarity:"uncommon",pol:{warm:1,act:-1},conceptFamily:"origin-grandparent",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170082,section:"Positive Origins",category:"Stable Care",trait:"Was fed when ill, without fuss",desc:"Sickness in childhood meant soup and a blanket and no drama; illness still feels like something that is simply managed.",example:"(temperature of 39. 'Right. Bed. Soup.' No panic anywhere.)",intensity:2,rarity:"common",pol:{disc:1,emo:-1},conceptFamily:"origin-nursed",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170083,section:"Positive Origins",category:"Stable Care",trait:"Parents who liked each other",desc:"Grew up watching two adults enjoy one another's company; expects partnership to be pleasant and is bewildered when it isn't.",example:"They used to laugh in the kitchen. I thought everyone's did.",intensity:3,rarity:"distinctive",pol:{warm:1,pos:1},conceptFamily:"origin-parents-liked",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170084,section:"Positive Origins",category:"Stable Care",trait:"Read to every night",desc:"A voice at the end of every day, for years; words and safety are the same thing to them.",example:"(still reads aloud to anyone who'll sit still, including adults)",intensity:2,rarity:"uncommon",pol:{warm:1,cur:1},conceptFamily:"origin-read-to",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170085,section:"Positive Origins",category:"Stable Care",trait:"A house that was warm",desc:"Physically warm, well-lit, with enough — the body learned early that the world could be comfortable.",example:"(turns the heating up without guilt. Puts a lamp in every corner.)",intensity:2,rarity:"common",pol:{pos:1},conceptFamily:"origin-warm-house",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170086,section:"Positive Origins",category:"Stable Care",trait:"Someone came to every match",desc:"Every game, recital or prize-giving had a face in the crowd, without fail; being watched feels like support, not scrutiny.",example:"(scans the audience for the face, out of habit, thirty years on. Finds a friend's instead. Same thing.)",intensity:3,rarity:"uncommon",pol:{ego:1,warm:1},conceptFamily:"origin-attended",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170087,section:"Positive Origins",category:"Stable Care",trait:"Allowed to be bored",desc:"Long, unscheduled childhood afternoons with nothing laid on; comfortable with an empty hour, and inventive in it.",example:"(no phone, no plan, a stick. Entirely content.)",intensity:2,rarity:"uncommon",pol:{cur:1,act:-1},conceptFamily:"origin-boredom",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170088,section:"Positive Origins",category:"Stable Care",trait:"Sent out to play and called in for tea",desc:"Freedom with a boundary — roam all day, be home by six — and both halves were reliable.",example:"(gives their own children the same. The street thinks they're mad. It works.)",intensity:3,rarity:"distinctive",pol:{disc:1,pos:1},conceptFamily:"origin-roam",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170089,section:"Positive Origins",category:"Stable Care",trait:"A bedroom that stayed theirs",desc:"The room was kept for them, unchanged, through every move away; there has always been somewhere to go back to.",example:"(the posters are still up. Forty. The posters are still up.)",intensity:3,rarity:"uncommon",pol:{warm:1},conceptFamily:"origin-room-kept",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170090,section:"Positive Origins",category:"Stable Care",trait:"Praised for effort, not results",desc:"Trying was what got noticed; failing was allowed. Takes risks easily and shrugs off losing.",example:"Didn't work. — What did you learn? — Loads. — Good.",intensity:3,rarity:"distinctive",pol:{pos:1,ego:1},conceptFamily:"origin-effort-praised",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170091,section:"Positive Origins",category:"Stable Care",trait:"Held when crying, not hushed",desc:"Tears were met with arms, not instructions to stop; feelings are things that pass through, not problems.",example:"(the friend is crying. They sit closer. Say nothing. It's the right thing.)",intensity:3,rarity:"uncommon",pol:{emo:1,warm:1},conceptFamily:"origin-held",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170092,section:"Positive Origins",category:"Stable Care",trait:"The dog that was always there",desc:"An animal through the whole of childhood; uncomplicated love has a face, and it had fur.",example:"(kneels to every dog in the street. Knows what it's for.)",intensity:2,rarity:"common",pol:{warm:1},conceptFamily:"origin-pet",behaviorFunction:"connect",reviewStatus:"reviewed"},

// ---- Earned Success
{id:170093,section:"Positive Origins",category:"Earned Success",trait:"Passed the exam nobody expected",desc:"One early, unlikely, entirely earned win; knows in the body that effort can pay.",example:"They'd written me off. I did the work. I'm not special; I just did the work.",intensity:3,rarity:"uncommon",pol:{disc:1,pos:1},conceptFamily:"origin-exam",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170094,section:"Positive Origins",category:"Earned Success",trait:"Built something that's still standing",desc:"A wall, a business, a garden, a club — made young, and still there; permanence is possible.",example:"(drives past it sometimes. Doesn't say anything. Doesn't need to.)",intensity:3,rarity:"distinctive",pol:{disc:1,ego:1},conceptFamily:"origin-built",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170095,section:"Positive Origins",category:"Earned Success",trait:"Was good at one thing at school",desc:"Not the star — but the one everyone knew could do that one thing; competence has always had a home.",example:"I was the maps kid. Still am, really.",intensity:2,rarity:"common",pol:{ego:1},conceptFamily:"origin-school-thing",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170096,section:"Positive Origins",category:"Earned Success",trait:"A mentor who said 'you're ready'",desc:"Someone with authority told them, once, that they could do it — before they believed it themselves.",example:"He put me on the job. I said I wasn't ready. He said 'I know. Go.' I went.",intensity:4,rarity:"signature",pol:{ego:1,warm:1},conceptFamily:"origin-mentor",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170097,section:"Positive Origins",category:"Earned Success",trait:"Paid off the debt, in full",desc:"A long, grinding, unglamorous repayment finished; knows exactly what a long haul feels like and that it ends.",example:"Six years. Every month. Then one month it was done. I bought a coat.",intensity:3,rarity:"uncommon",pol:{disc:1},conceptFamily:"origin-debt-paid",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170098,section:"Positive Origins",category:"Earned Success",trait:"Won something small and fair",desc:"A local prize, a race, a competition — small, honestly won, and remembered as proof the world sometimes works.",example:"(the certificate is in the loft. They could tell you the date.)",intensity:2,rarity:"common",pol:{pos:1},conceptFamily:"origin-small-win",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170099,section:"Positive Origins",category:"Earned Success",trait:"Turned a bad year around by hand",desc:"Fell a long way once and climbed out through plain work; failure holds no terror because they've done the climb.",example:"Lost the lot in '09. Was fine by '11. It's just work. Work's not scary.",intensity:4,rarity:"distinctive",pol:{disc:1,pos:1,ego:1},conceptFamily:"origin-recovered",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170100,section:"Positive Origins",category:"Earned Success",trait:"Recognised by the people who knew",desc:"Never famous — but the small circle who understood the work said so, and that was enough.",example:"Two people in the world know what that took. They both told me. That's plenty.",intensity:3,rarity:"distinctive",pol:{ego:1},conceptFamily:"origin-peer-recognition",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170101,section:"Positive Origins",category:"Earned Success",trait:"Taught themselves out of it",desc:"Escaped a bad situation by learning something — a skill, a language, a trade — alone, at night; learning is freedom.",example:"(the library card was the way out. Still uses the library.)",intensity:4,rarity:"uncommon",pol:{cur:1,disc:1},conceptFamily:"origin-self-taught-escape",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170102,section:"Positive Origins",category:"Earned Success",trait:"Raised a sibling, and it went well",desc:"Took on real care young and the person turned out fine; competence at looking after people was proven early.",example:"She's a doctor now. I did the packed lunches. I'm taking partial credit.",intensity:4,rarity:"distinctive",pol:{warm:1,disc:1},conceptFamily:"origin-raised-sibling",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170103,section:"Positive Origins",category:"Earned Success",trait:"A trade that always found work",desc:"Learned something the world needs and has never once been without a job; security is a skill, not luck.",example:"There's always pipes. There'll always be pipes.",intensity:2,rarity:"common",pol:{disc:1,pos:1},conceptFamily:"origin-trade-security",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170104,section:"Positive Origins",category:"Earned Success",trait:"Chosen for the team, on merit",desc:"Picked, once, by someone who had no reason to be kind, purely for being good; carries that certainty.",example:"She didn't like me. She picked me anyway. That's the one that counts.",intensity:3,rarity:"uncommon",pol:{ego:1},conceptFamily:"origin-picked",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170105,section:"Positive Origins",category:"Earned Success",trait:"Finished the thing nobody finishes",desc:"The degree, the boat, the book, the walk — a long project seen to the end; knows the last mile is real.",example:"(most people stop at eighty percent. They know what ninety feels like.)",intensity:3,rarity:"distinctive",pol:{disc:1},conceptFamily:"origin-finished",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170106,section:"Positive Origins",category:"Earned Success",trait:"Ordinary, and content with it",desc:"No dramatic triumph — a decent job, a paid-for house, people who ring; regards this as a success, and it is.",example:"It's a good life. Nobody's written a book about it. Doesn't need one.",intensity:2,rarity:"uncommon",pol:{pos:1,ego:1},conceptFamily:"origin-ordinary",behaviorFunction:"soothe",reviewStatus:"reviewed"},

// ---- Repaired Conflict
{id:170107,section:"Positive Origins",category:"Repaired Conflict",trait:"The estrangement that ended",desc:"Years of silence with a parent or sibling, then a real reconciliation; knows that rifts can close, and how.",example:"Eight years. Then a phone call. Now Sunday lunch. It's possible. I'm proof.",intensity:4,rarity:"distinctive",pol:{warm:1,agr:1},conceptFamily:"origin-estrangement-ended",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170108,section:"Positive Origins",category:"Repaired Conflict",trait:"Fought with a friend and stayed friends",desc:"A real, ugly falling-out survived; friendship is understood as something that can take a hit.",example:"We didn't speak for a month. We've been closer since. That's what a month's for.",intensity:3,rarity:"uncommon",pol:{warm:1},conceptFamily:"origin-friendship-survived",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170109,section:"Positive Origins",category:"Repaired Conflict",trait:"Apologised first, and it worked",desc:"Went to someone they'd wronged, said it plainly, and was received; has done it since without fear.",example:"I said I was wrong. He said 'yeah'. Then he put the kettle on. That's it. That's the whole trick.",intensity:3,rarity:"distinctive",pol:{hon:1,agr:1},conceptFamily:"origin-apology-worked",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170110,section:"Positive Origins",category:"Repaired Conflict",trait:"Watched two adults make up",desc:"Saw a real argument, saw it resolved, saw the people afterwards; conflict is a weather, not a verdict.",example:"They shouted. Then they were fine. So shouting's just — shouting.",intensity:2,rarity:"common",pol:{agr:1,pos:1},conceptFamily:"origin-watched-repair",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170111,section:"Positive Origins",category:"Repaired Conflict",trait:"The neighbour dispute that became a friendship",desc:"Started as enemies over a fence, a noise, a parking space; ended as the person they'd call first.",example:"He hated me. I hated him. Now he's got a key. Don't ask me how.",intensity:3,rarity:"uncommon",pol:{warm:1},conceptFamily:"origin-neighbour",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170112,section:"Positive Origins",category:"Repaired Conflict",trait:"Was the one who went back",desc:"Walked out, once, and walked back in an hour later; knows leaving isn't the end unless you let it be.",example:"Got to the end of the road. Thought about it. Came back. Best thing I ever did.",intensity:3,rarity:"distinctive",pol:{warm:1,disc:1},conceptFamily:"origin-went-back",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170113,section:"Positive Origins",category:"Repaired Conflict",trait:"Mediated the family, at fifteen",desc:"Stood between warring adults young and got them to a table; assumes peace is a thing you build, not wait for.",example:"(still the one everyone rings when two of the others have fallen out)",intensity:4,rarity:"signature",pol:{agr:1,asrt:1},conceptFamily:"origin-mediator",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170114,section:"Positive Origins",category:"Repaired Conflict",trait:"Kept in touch after the divorce",desc:"Parents split and stayed civil, even kind; separation doesn't have to mean war, and they don't expect it to.",example:"They still do Christmas together. Different houses, same table. It's fine. It's actually fine.",intensity:3,rarity:"uncommon",pol:{agr:1,pos:1},conceptFamily:"origin-civil-divorce",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170115,section:"Positive Origins",category:"Repaired Conflict",trait:"Got the truth out, and the room survived",desc:"A family secret finally spoken and nobody died of it; truth-telling is remembered as relief, not catastrophe.",example:"We all knew. Someone finally said it. The ceiling stayed up.",intensity:4,rarity:"distinctive",pol:{hon:1,emo:1},conceptFamily:"origin-truth-survived",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170116,section:"Positive Origins",category:"Repaired Conflict",trait:"Forgave a debt and gained a friend",desc:"Let something owed go, deliberately, and got something better back; keeps score loosely as a result.",example:"He couldn't pay. I said forget it. Twenty years later he carried my mother's coffin.",intensity:3,rarity:"uncommon",pol:{warm:1,agr:1},conceptFamily:"origin-debt-forgiven",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170117,section:"Positive Origins",category:"Repaired Conflict",trait:"Learned to say 'I was scared'",desc:"Once, mid-fight, said the true thing instead of the sharp one, and it changed everything; reaches for it now.",example:"I stopped shouting and said I was frightened. She stopped too. That was the end of that war.",intensity:4,rarity:"distinctive",pol:{emo:1,hon:1},conceptFamily:"origin-vulnerable-truth",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170118,section:"Positive Origins",category:"Repaired Conflict",trait:"The team that argued and shipped",desc:"Part of a group that fought hard about the work and delivered anyway; disagreement is fuel, not damage.",example:"Best thing we ever made. We hated each other for six weeks. Both true.",intensity:3,rarity:"uncommon",pol:{agr:-1,pos:1},conceptFamily:"origin-productive-conflict",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170119,section:"Positive Origins",category:"Repaired Conflict",trait:"Was told 'we'll sort it' and it was sorted",desc:"Childhood catastrophes handled by adults who said it would be all right and made it so; crisis has a shape, and an end.",example:"(the car's on fire. 'Right. Well. Let's sort it.' Same voice as Dad's.)",intensity:3,rarity:"distinctive",pol:{disc:1,pos:1},conceptFamily:"origin-sorted",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170120,section:"Positive Origins",category:"Repaired Conflict",trait:"Made peace with the town",desc:"Left under a cloud, came back, was accepted; belonging can be lost and regained.",example:"They didn't want me back. Then they did. You just keep turning up.",intensity:4,rarity:"signature",pol:{warm:1,disc:1},conceptFamily:"origin-town-peace",behaviorFunction:"repair",reviewStatus:"reviewed"},

// ================================================================ GOALS & STAKES (draws one of each)
// ---- Immediate Objective
{id:170121,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get through Friday",desc:"The horizon is the end of the week — one payment, one shift, one conversation — and everything else waits.",example:"Friday. Ask me about anything after Friday, after Friday.",intensity:2,rarity:"common",pol:{act:-1},conceptFamily:"goal-survive-week",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170122,section:"Goals & Stakes",category:"Immediate Objective",trait:"Find the money by the end of the month",desc:"A specific sum, a specific date, and a visible mental count running in every conversation.",example:"(nods along; is adding up the rent under the table)",intensity:4,rarity:"common",pol:{disc:1,mood:-1},conceptFamily:"goal-money-deadline",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170123,section:"Goals & Stakes",category:"Immediate Objective",trait:"Have the conversation they've been avoiding",desc:"One talk — with a parent, a partner, a boss — rehearsed daily and not yet had; it colours every other exchange.",example:"(opens their mouth. Closes it. 'Nothing. Doesn't matter. Tomorrow.')",intensity:3,rarity:"uncommon",pol:{emo:1,asrt:-1},conceptFamily:"goal-conversation",behaviorFunction:"avoid",reviewStatus:"reviewed"},
{id:170124,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get the result back",desc:"A test, a verdict, a letter — waiting on one piece of news that will decide the next year, and pretending not to be.",example:"No, I'm fine. (checks the phone. Checks it again.)",intensity:4,rarity:"uncommon",pol:{mood:-1},conceptFamily:"goal-awaiting-news",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170125,section:"Goals & Stakes",category:"Immediate Objective",trait:"Finish the thing on the bench",desc:"A concrete, half-done piece of work that is thought about constantly and returned to at every free moment.",example:"(the conversation is fine. The hands are still on the chair leg in the workshop.)",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"goal-finish-work",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170126,section:"Goals & Stakes",category:"Immediate Objective",trait:"Keep them from finding out",desc:"A short-term concealment — of a debt, a diagnosis, a failure — that governs what can be said this week.",example:"(steers every conversation away from the garage, the post, the doctor)",intensity:4,rarity:"distinctive",pol:{hon:-1,emo:-1},conceptFamily:"goal-conceal",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170127,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get the kid through the exam",desc:"Someone else's deadline has become the whole of their present — timetables, meals, silence in the house.",example:"Not till June. Nothing happens in this house till June.",intensity:3,rarity:"common",pol:{warm:1,disc:1},conceptFamily:"goal-someone-elses",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170128,section:"Goals & Stakes",category:"Immediate Objective",trait:"Win the argument that's coming",desc:"A known confrontation on the calendar, prepared for like a match, with notes.",example:"(has three counter-arguments ready for a meeting that's still nine days away)",intensity:3,rarity:"uncommon",pol:{asrt:1},conceptFamily:"goal-confrontation",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170129,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get out of the house, today",desc:"One small immediate aim — leave the room, walk to the shop, see one person — that is harder than it sounds and matters more.",example:"Made it to the corner. That's today done. That's a good day.",intensity:2,rarity:"distinctive",pol:{mood:-1,act:-1},conceptFamily:"goal-small-step",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170130,section:"Goals & Stakes",category:"Immediate Objective",trait:"Be there when it happens",desc:"A birth, a death, a landing, a verdict — there is one moment they must not miss, and every plan bends round it.",example:"I'll be there. I don't care about the meeting. I'll be there.",intensity:5,rarity:"uncommon",pol:{warm:1,disc:1},conceptFamily:"goal-be-present",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170131,section:"Goals & Stakes",category:"Immediate Objective",trait:"Land the job on Thursday",desc:"One interview, one pitch, one audition — the next four days are a runway and everything is fuel.",example:"(has ironed the shirt twice. It's Monday.)",intensity:4,rarity:"common",pol:{disc:1},conceptFamily:"goal-interview",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170132,section:"Goals & Stakes",category:"Immediate Objective",trait:"Stop, for one more day",desc:"Not drinking, not calling, not going back — the objective is measured in single days and restarted often.",example:"Today. Just today. I'll do tomorrow tomorrow.",intensity:4,rarity:"distinctive",pol:{disc:1,mood:-1},conceptFamily:"goal-abstain",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170133,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get the animal to the vet",desc:"A small, practical, urgent care task for something that depends on them, standing in for everything else that's out of their hands.",example:"(the world's on fire. The cat has an appointment at four. The cat's appointment is real.)",intensity:2,rarity:"common",pol:{warm:1},conceptFamily:"goal-care-task",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170134,section:"Goals & Stakes",category:"Immediate Objective",trait:"Make it up to them by the weekend",desc:"A specific wrong done recently, and a plan — a gesture, a favour, a meal — to put it right before it sets.",example:"(has booked the restaurant. Hasn't said sorry yet. The restaurant is the sorry.)",intensity:3,rarity:"uncommon",pol:{agr:1,warm:1},conceptFamily:"goal-make-amends",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170135,section:"Goals & Stakes",category:"Immediate Objective",trait:"Sell it before they notice",desc:"A quiet, time-pressured disposal — of an asset, an idea, a position — that has to complete before someone asks questions.",example:"(the listing is up. The listing is not mentioned.)",intensity:4,rarity:"distinctive",pol:{hon:-1,disc:1},conceptFamily:"goal-quiet-sale",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170136,section:"Goals & Stakes",category:"Immediate Objective",trait:"Say it before the flight",desc:"A declaration — of love, of leaving, of the truth — with a fixed moment it has to happen by.",example:"(the gate closes at nine. There are eleven minutes.)",intensity:5,rarity:"signature",pol:{emo:1,asrt:1},conceptFamily:"goal-declare",behaviorFunction:"connect",reviewStatus:"reviewed"},

// ---- The Longer Aim
{id:170137,section:"Goals & Stakes",category:"The Longer Aim",trait:"Own the shop outright",desc:"A concrete, multi-year ambition — the place, the name over the door, no landlord — with a plan and a date.",example:"Four more years. Then it's mine. Then I paint it green.",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"aim-ownership",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170138,section:"Goals & Stakes",category:"The Longer Aim",trait:"Get the child to a different life",desc:"Every decision measured against whether it moves the next generation out of what this one had.",example:"She won't do what I did. That's the whole point of me.",intensity:4,rarity:"common",pol:{warm:1,disc:1},conceptFamily:"aim-next-generation",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170139,section:"Goals & Stakes",category:"The Longer Aim",trait:"Be forgiven by one specific person",desc:"A years-long, patient, unrushed project of becoming someone that person could forgive.",example:"(the letters go unanswered. They keep going. That's the plan; there isn't another one.)",intensity:4,rarity:"distinctive",pol:{emo:1,disc:1},conceptFamily:"aim-forgiveness",behaviorFunction:"repair",reviewStatus:"reviewed"},
{id:170140,section:"Goals & Stakes",category:"The Longer Aim",trait:"Leave the town for good",desc:"A slow, deliberate, funded exit from where they were born, with a destination in mind.",example:"(the savings account is called 'Lisbon'. It's not a joke.)",intensity:3,rarity:"uncommon",pol:{rebel:1,cur:1},conceptFamily:"aim-leave",behaviorFunction:"avoid",reviewStatus:"reviewed"},
{id:170141,section:"Goals & Stakes",category:"The Longer Aim",trait:"Master the craft, however long it takes",desc:"A decade-scale commitment to getting genuinely good at one thing, in the face of slow progress.",example:"Year eleven. I'm nearly competent. Year twenty, maybe good.",intensity:3,rarity:"distinctive",pol:{disc:1,cur:1},conceptFamily:"aim-mastery",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170142,section:"Goals & Stakes",category:"The Longer Aim",trait:"Retire with the boat",desc:"An ordinary, specific, dreamed-of end state — a boat, a cottage, a garden — that makes the current grind bearable.",example:"(the brochure is in the drawer. Has been for nine years. Is looked at monthly.)",intensity:2,rarity:"common",pol:{pos:1},conceptFamily:"aim-retirement",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170143,section:"Goals & Stakes",category:"The Longer Aim",trait:"Clear the name",desc:"A long campaign to reverse a verdict, a rumour or a record — theirs or someone else's — pursued through every channel.",example:"Appeal denied. Right. Next appeal.",intensity:4,rarity:"uncommon",pol:{disc:1,hon:1},conceptFamily:"aim-vindication",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170144,section:"Goals & Stakes",category:"The Longer Aim",trait:"Keep the farm in the family",desc:"Not growth, not escape — holding on to something inherited against everything pulling it apart.",example:"Two hundred years. Not losing it on my watch. Not on mine.",intensity:4,rarity:"distinctive",pol:{disc:1,rebel:-1},conceptFamily:"aim-keep",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170145,section:"Goals & Stakes",category:"The Longer Aim",trait:"Find out what really happened",desc:"A slow investigation into an old event — a death, a disappearance, a decision — that structures years of quiet effort.",example:"(the folder is thick now. Twelve years of letters. Nearly there.)",intensity:4,rarity:"uncommon",pol:{cur:1,disc:1},conceptFamily:"aim-truth",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170146,section:"Goals & Stakes",category:"The Longer Aim",trait:"Be the one who's still standing",desc:"Outlast — the rivals, the doubters, the institution — by simply not stopping.",example:"They'll all be gone. I'll still be here. That's the plan. It's a slow plan.",intensity:3,rarity:"distinctive",pol:{disc:1,rebel:1},conceptFamily:"aim-outlast",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170147,section:"Goals & Stakes",category:"The Longer Aim",trait:"Build the thing that doesn't exist yet",desc:"A specific invention, institution or work that nobody has made, pursued through years of being told it can't be done.",example:"(the prototype is in the shed. The seventh prototype. The eighth is on the bench.)",intensity:4,rarity:"signature",pol:{cur:1,pos:1},conceptFamily:"aim-build",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170148,section:"Goals & Stakes",category:"The Longer Aim",trait:"Never need anyone again",desc:"Financial, physical and emotional self-sufficiency as a destination, worked toward with quiet ferocity.",example:"(learns to fix the boiler. Learns to do the tax. Learns to be alone. On schedule.)",intensity:4,rarity:"distinctive",pol:{warm:-1,disc:1},conceptFamily:"aim-independence",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170149,section:"Goals & Stakes",category:"The Longer Aim",trait:"See the grandchildren grown",desc:"A long-horizon aim measured in other people's birthdays, that shapes every decision about health and risk.",example:"(gave up the cigarettes at sixty-one. Not for himself. For a wedding in 2040.)",intensity:3,rarity:"common",pol:{warm:1,pos:1},conceptFamily:"aim-grandchildren",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170150,section:"Goals & Stakes",category:"The Longer Aim",trait:"Go back and do it properly",desc:"The degree, the apprenticeship, the thing abandoned young — returned to, deliberately, in middle age.",example:"Started at nineteen. Quit at twenty. Enrolled again at forty-four. Finishing this time.",intensity:3,rarity:"uncommon",pol:{disc:1,cur:1},conceptFamily:"aim-return",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170151,section:"Goals & Stakes",category:"The Longer Aim",trait:"Make enough to stop",desc:"A precise figure, after which they intend to walk away from all of it; the figure occasionally moves.",example:"The number's the number. — It was a different number last year. — The number's the number.",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"aim-enough",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170152,section:"Goals & Stakes",category:"The Longer Aim",trait:"Be remembered for one true thing",desc:"Not fame — one piece of work, one act, one made thing that will outlast them and be theirs.",example:"One bridge. Just one. With my name on the plaque, small, at the bottom.",intensity:4,rarity:"distinctive",pol:{ego:1,disc:1},conceptFamily:"aim-legacy",behaviorFunction:"provide",reviewStatus:"reviewed"},

// ---- The Price & The Competing Claim
{id:170153,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The marriage is the price",desc:"Whatever they're after, it costs time and presence at home, and everyone at home knows the tariff.",example:"(the anniversary dinner is pencilled. Everything is pencilled.)",intensity:4,rarity:"common",pol:{warm:-1,disc:1},conceptFamily:"price-marriage",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170154,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"A parent who needs them now",desc:"An ageing relative's care sits directly across the path of the goal, and both are non-negotiable.",example:"I can't move. Mum's here. Mum's here for as long as Mum's here.",intensity:4,rarity:"common",pol:{warm:1,disc:1},conceptFamily:"claim-parent",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170155,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The health they're spending",desc:"The goal is being paid for out of sleep, joints and blood pressure, visibly, and they've decided that's acceptable.",example:"(the doctor said rest. The doctor doesn't have a deadline.)",intensity:4,rarity:"uncommon",pol:{disc:1,act:1},conceptFamily:"price-health",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170156,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"A promise made to someone else",desc:"An earlier commitment — to a friend, a crew, a cause — that the new goal quietly breaks, and they know it.",example:"I told Sam I'd stay till the end. This isn't the end. But it's my chance.",intensity:4,rarity:"distinctive",pol:{hon:1,agr:1},conceptFamily:"claim-promise",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170157,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The reputation on the line",desc:"If it fails, it fails in public, and the name goes with it; the stake is who they get to be afterwards.",example:"If this doesn't work, I'm the one who tried. For the rest of my life, that's the sentence.",intensity:4,rarity:"uncommon",pol:{ego:-1,disc:1},conceptFamily:"price-reputation",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170158,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Their own quiet, given up",desc:"The goal means people, noise, exposure — and they are someone who needs none of those, and is paying in them.",example:"(hates the meetings. Goes to all of them. The thing needs the meetings.)",intensity:3,rarity:"distinctive",pol:{act:-1,warm:-1},conceptFamily:"price-quiet",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170159,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Two children, one bursary",desc:"Resources that can serve one goal or one person, not both; a choice that has to be made and can't be made fairly.",example:"(the fund covers one course. There are two of them. Nobody talks about it.)",intensity:5,rarity:"uncommon",pol:{warm:1,mood:-1},conceptFamily:"claim-siblings",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170160,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The friend who'll be left behind",desc:"Success means leaving someone who can't follow, and both of them can see it coming.",example:"You'll go. — I might not. — You'll go. It's fine. I'd go.",intensity:4,rarity:"distinctive",pol:{warm:1,mood:-1},conceptFamily:"claim-friend",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170161,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Money they can't quite afford to risk",desc:"The goal is funded from savings that were for something safer, and the safer thing hasn't gone away.",example:"(the deposit is now the stake. The deposit was the deposit.)",intensity:3,rarity:"common",pol:{disc:-1,mood:-1},conceptFamily:"price-savings",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170162,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The job that pays for the dream",desc:"Work they dislike, kept deliberately because it funds the thing they love; the resentment is budgeted.",example:"Eight hours for them. Three for me. It's a fair deal. It's not a good one.",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"price-day-job",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170163,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Loyalty to the place versus the way out",desc:"Leaving would be the sane thing; staying is what the people here expect and what they half want.",example:"Everyone who could leave has left. Which tells you something. I'm still here. Which tells you something else.",intensity:3,rarity:"distinctive",pol:{agr:1,rebel:-1},conceptFamily:"claim-place",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170164,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The truth they'd have to tell",desc:"Getting what they want requires admitting something they've hidden, and they haven't decided if it's worth it.",example:"(could have the job by Friday. Would have to explain 2016 first.)",intensity:4,rarity:"uncommon",pol:{hon:-1,emo:-1},conceptFamily:"price-disclosure",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170165,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Someone will lose so they can win",desc:"The goal is zero-sum, and they know exactly who pays; they are trying not to know it too clearly.",example:"There's one post. Dee wants it too. Dee's been here longer. So.",intensity:4,rarity:"distinctive",pol:{agr:-1,hon:1},conceptFamily:"price-zero-sum",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170166,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The self they'd have to become",desc:"Succeeding would mean being a kind of person they've always disliked, and they can feel it starting.",example:"(caught themselves doing the voice. The voice they used to mock.)",intensity:4,rarity:"signature",pol:{hon:1,ego:-1},conceptFamily:"price-identity",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170167,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The animals, the land, the season",desc:"Something living depends on them on a schedule that doesn't bend, and the goal keeps asking it to.",example:"Can't be there in April. Lambing. April's not mine.",intensity:3,rarity:"uncommon",pol:{disc:1,warm:1},conceptFamily:"claim-season",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170168,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"No price they can name, which worries them",desc:"Everything is going their way and nothing seems to cost anything; they keep looking for the bill.",example:"It's too easy. Something's coming. Something's always coming.",intensity:2,rarity:"distinctive",pol:{pos:-1},conceptFamily:"price-none",behaviorFunction:"protect",reviewStatus:"reviewed"},

// ---- Goals & Stakes, second packet. Measured at 16 per category the section became
// the worst fixed slot in the bank (top-1 19%, effective diversity 11.6 at defaults),
// because the default profile weight targets ~2.4 and most of the first packet sat at
// intensity 3-4. These sit deliberately at the quiet end and the extreme end.
{id:170329,section:"Goals & Stakes",category:"Immediate Objective",trait:"Return the library book",desc:"A small, overdue, faintly shaming errand that has become the emblem of everything else undone.",example:"(it's been on the hall table for eleven weeks. It is, somehow, the whole problem.)",intensity:1,rarity:"common",pol:{disc:-1},conceptFamily:"goal-small-errand",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170330,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get a full night's sleep",desc:"The horizon has shrunk to one uninterrupted night, which keeps not arriving.",example:"Tonight. Just eight hours. Then I'll be a person again.",intensity:2,rarity:"common",pol:{act:-1,mood:-1},conceptFamily:"goal-sleep",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170331,section:"Goals & Stakes",category:"Immediate Objective",trait:"Answer the message from last week",desc:"One reply, owed and dreaded, that grows harder by the day it isn't sent.",example:"(opens the thread. Types. Deletes. Nine days now.)",intensity:2,rarity:"common",pol:{asrt:-1},conceptFamily:"goal-reply",behaviorFunction:"avoid",reviewStatus:"reviewed"},
{id:170332,section:"Goals & Stakes",category:"Immediate Objective",trait:"Fix the leak before the landlord sees",desc:"A concrete, practical, ticking task with an audience it must be finished before.",example:"(inspection Tuesday. It's Sunday. There's a bucket.)",intensity:2,rarity:"common",pol:{disc:1},conceptFamily:"goal-fix-before",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170333,section:"Goals & Stakes",category:"Immediate Objective",trait:"Book the appointment they keep not booking",desc:"A single phone call, medical or otherwise, that everyone has reminded them about and that remains unmade.",example:"I'll do it Monday. — You said Monday. — A different Monday.",intensity:1,rarity:"common",pol:{disc:-1,emo:-1},conceptFamily:"goal-appointment",behaviorFunction:"avoid",reviewStatus:"reviewed"},
{id:170334,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get to the end of the shift",desc:"Nothing beyond the next eight hours exists; the objective is the clock.",example:"(looks at the clock. Looks at the clock. Looks at the clock.)",intensity:2,rarity:"common",pol:{act:-1},conceptFamily:"goal-shift",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170335,section:"Goals & Stakes",category:"Immediate Objective",trait:"Learn the six lines by Thursday",desc:"A small, specific, slightly public performance looming, prepared for out loud in every private moment.",example:"(muttering in the queue. Muttering in the shower. Six lines.)",intensity:2,rarity:"uncommon",pol:{disc:1,ego:-1},conceptFamily:"goal-lines",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170336,section:"Goals & Stakes",category:"Immediate Objective",trait:"Keep the plant alive till she's back",desc:"Something small entrusted to them for a short, specific period, treated as a matter of honour.",example:"(watered. Turned toward the light. Talked to. It's a fern. It matters.)",intensity:1,rarity:"uncommon",pol:{warm:1,disc:1},conceptFamily:"goal-entrusted",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170337,section:"Goals & Stakes",category:"Immediate Objective",trait:"Not cry at the meeting",desc:"An objective measured entirely in composure, for one hour, in one room.",example:"(nails in the palm. Breathing. Nodding. Made it to the lift.)",intensity:3,rarity:"uncommon",pol:{emo:-1,disc:1},conceptFamily:"goal-composure",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170338,section:"Goals & Stakes",category:"Immediate Objective",trait:"Find the document",desc:"One piece of paper — a certificate, a deed, a letter — that has to be found this week and is nowhere.",example:"(every drawer in the house is open. It's not in any of them.)",intensity:2,rarity:"common",pol:{disc:-1},conceptFamily:"goal-find",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170339,section:"Goals & Stakes",category:"Immediate Objective",trait:"Say no to the favour, this time",desc:"A request is coming and the objective, rehearsed and doubtful, is to refuse it.",example:"(has the sentence ready. Has had it ready for three years. Has never used it.)",intensity:2,rarity:"uncommon",pol:{asrt:-1,agr:1},conceptFamily:"goal-refuse",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170340,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get the money to them before the deadline",desc:"Someone else's rent, fine or fee, which they have taken on and must deliver, today, without being thanked.",example:"(the envelope. The bus. Before four. Nobody will know.)",intensity:3,rarity:"distinctive",pol:{warm:1,disc:1},conceptFamily:"goal-deliver",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170341,section:"Goals & Stakes",category:"Immediate Objective",trait:"Win back the room by lunchtime",desc:"A morning that went badly, and an afternoon that has to reverse it, publicly and fast.",example:"(the first presentation died. The second one starts at one. Everything is in the second one.)",intensity:5,rarity:"distinctive",pol:{asrt:1,ego:-1},conceptFamily:"goal-recover-room",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170342,section:"Goals & Stakes",category:"Immediate Objective",trait:"Get everyone home",desc:"A short, total responsibility — a crew, a family, a class — that must be safely delivered before anything else is allowed to matter.",example:"Count. Again. — We've counted. — Count again. Then we go.",intensity:5,rarity:"signature",pol:{disc:1,warm:1},conceptFamily:"goal-everyone-home",behaviorFunction:"protect",reviewStatus:"reviewed",conditions:["threat"]},
{id:170343,section:"Goals & Stakes",category:"The Longer Aim",trait:"Learn to swim, eventually",desc:"A modest, private, long-postponed aim, mentioned lightly and meant seriously.",example:"One day. Properly. Not the doggy paddle. One day.",intensity:1,rarity:"common",pol:{pos:1},conceptFamily:"aim-swim",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170344,section:"Goals & Stakes",category:"The Longer Aim",trait:"Have a garden with a bench in it",desc:"A small, specific, unambitious picture of the good life, held onto through years that don't resemble it.",example:"(no garden. A bench in the plan, though. There's always been a bench in the plan.)",intensity:1,rarity:"common",pol:{pos:1,act:-1},conceptFamily:"aim-bench",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170345,section:"Goals & Stakes",category:"The Longer Aim",trait:"Be the kind of person people ring",desc:"Not fame or wealth — to become someone whose number is the one dialled in trouble.",example:"(nobody rings them yet. They are working on being the sort of person who gets rung.)",intensity:2,rarity:"uncommon",pol:{warm:1},conceptFamily:"aim-be-rung",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170346,section:"Goals & Stakes",category:"The Longer Aim",trait:"Read the whole shelf",desc:"A quiet, years-long private curriculum, worked through one book at a time with no one to report to.",example:"(third shelf, fourth book. Started in 2019. No rush.)",intensity:1,rarity:"uncommon",pol:{cur:1,disc:1},conceptFamily:"aim-read",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170347,section:"Goals & Stakes",category:"The Longer Aim",trait:"Get the old friends in one room again",desc:"A reunion planned for years, blocked by geography, feuds and diaries, and never given up.",example:"(the group chat has been trying to fix a date since 2017. They are the one still trying.)",intensity:2,rarity:"common",pol:{warm:1,disc:1},conceptFamily:"aim-reunion",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170348,section:"Goals & Stakes",category:"The Longer Aim",trait:"Pay for the parents' roof",desc:"A specific, dutiful, long-range financial aim held quietly on behalf of people who would refuse it if asked.",example:"(the fund is called 'roof'. They don't know about the fund. They will.)",intensity:2,rarity:"uncommon",pol:{warm:1,disc:1},conceptFamily:"aim-parents-roof",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170349,section:"Goals & Stakes",category:"The Longer Aim",trait:"Move nearer the sea",desc:"A gentle, decades-long drift of intention toward a coast, one house move at a time.",example:"(each move has been a little further west. Nobody has said why. It's the sea.)",intensity:1,rarity:"common",pol:{pos:1},conceptFamily:"aim-sea",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170350,section:"Goals & Stakes",category:"The Longer Aim",trait:"Be there for the whole of someone's childhood",desc:"Not to miss it — the aim is presence across years, and it shapes every job offer and every trip.",example:"Turned it down. It's in Singapore. She's six. I'm not doing six from Singapore.",intensity:2,rarity:"uncommon",pol:{warm:1,act:-1},conceptFamily:"aim-presence",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170351,section:"Goals & Stakes",category:"The Longer Aim",trait:"Get good enough to teach it",desc:"Mastery aimed at handing on — the point of getting good is to be able to give it away.",example:"Another few years. Then I'll take an apprentice. That's what it's for.",intensity:2,rarity:"uncommon",pol:{warm:1,disc:1},conceptFamily:"aim-teach",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170352,section:"Goals & Stakes",category:"The Longer Aim",trait:"Die in the house they were born in",desc:"A fixed, long-range intention about place that outranks money, convenience and advice.",example:"I'm not going anywhere. They can carry me out. That's the plan; it's a simple plan.",intensity:5,rarity:"distinctive",pol:{rebel:-1,disc:1},conceptFamily:"aim-stay-to-the-end",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170353,section:"Goals & Stakes",category:"The Longer Aim",trait:"See it finished before they go",desc:"One work — a building, a book, a case, a child's settling — that has to reach its end inside their own lifetime, and the clock is audible.",example:"(the doctor said maybe two years. The last volume needs three. So: two.)",intensity:5,rarity:"signature",pol:{disc:1,mood:-1},conceptFamily:"aim-finish-in-time",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170354,section:"Goals & Stakes",category:"The Longer Aim",trait:"Never be that hungry again",desc:"An early scarcity turned into a lifelong, quiet, unnegotiable aim about security — the freezer, the account, the spare.",example:"(there are tins for a month. There will always be tins for a month.)",intensity:4,rarity:"distinctive",pol:{disc:1,mood:-1},conceptFamily:"aim-never-hungry",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170355,section:"Goals & Stakes",category:"The Longer Aim",trait:"Be forgotten, on purpose",desc:"To leave no trace — to be unremembered, unfound, unrecorded — pursued as carefully as fame is by others.",example:"(no photographs. No plaque. Paid cash. The plan is working.)",intensity:5,rarity:"signature",pol:{warm:-1,rebel:1},conceptFamily:"aim-vanish",behaviorFunction:"avoid",reviewStatus:"reviewed"},
{id:170356,section:"Goals & Stakes",category:"The Longer Aim",trait:"A dog, when there's time",desc:"A small deferred happiness, always one life-stage away, and genuinely intended.",example:"When things settle. Then a dog. A proper one. When things settle.",intensity:1,rarity:"common",pol:{warm:1,pos:1},conceptFamily:"aim-dog",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170357,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The weekend they never get",desc:"A modest cost — Saturdays, mostly — paid steadily and noticed only by the people who used to see them then.",example:"(hasn't had a Saturday off since the spring. Says it's fine. It's mostly fine.)",intensity:2,rarity:"common",pol:{disc:1},conceptFamily:"price-weekends",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170358,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"A hobby quietly dropped",desc:"Something loved — the choir, the boat, the Thursday game — set down to make room, and missed more than admitted.",example:"(the guitar is in its case. The case is in the loft. 'When things calm down.')",intensity:1,rarity:"common",pol:{mood:-1},conceptFamily:"price-hobby",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170359,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The friend who thinks they've changed",desc:"Not a rupture — a slow, unspoken drift from someone who has noticed the goal taking up the space they used to have.",example:"You're different. — I'm busy. — That's what I said.",intensity:2,rarity:"uncommon",pol:{warm:-1},conceptFamily:"price-drift",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170360,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"A garden gone to seed",desc:"Something small and living neglected for the sake of the larger thing, visible from the kitchen window every morning.",example:"(the beds are weeds. They see them daily. They'll get to them. They won't.)",intensity:1,rarity:"common",pol:{disc:-1},conceptFamily:"price-garden",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170361,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The bedtime story someone else reads",desc:"A nightly absence, small each time and large in sum, that the goal is costing.",example:"(rings at seven to say goodnight. Is told 'she's asleep'. Again.)",intensity:3,rarity:"common",pol:{warm:1,mood:-1},conceptFamily:"price-bedtime",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170362,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Being the one who always has to say no",desc:"The goal makes them the household's refuser — of trips, of treats, of the easier road — and they feel the role settling on them.",example:"Can we— — No. — Why is it always— — Because it's always me. I know.",intensity:2,rarity:"uncommon",pol:{disc:1,agr:-1},conceptFamily:"price-refuser",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170363,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"A small vanity given up",desc:"The haircut, the good coat, the thing they used to do for themselves — surrendered to the budget, and noticed in mirrors.",example:"(cuts their own hair now. It's fine. It's not what it was.)",intensity:1,rarity:"common",pol:{ego:-1},conceptFamily:"price-vanity",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170364,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The sibling who does the visits",desc:"Someone else carries the family duty — the hospital, the parents, the forms — while they pursue the thing, and both of them keep count.",example:"She goes every week. I go at Christmas. I'm aware. She makes sure I'm aware.",intensity:2,rarity:"uncommon",pol:{warm:-1,hon:1},conceptFamily:"price-sibling-duty",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170365,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Sleep, traded knowingly",desc:"A deliberate, calculated loan taken out against their own rest, with a repayment date they keep moving.",example:"Five hours is fine. — It's not. — It's fine till March.",intensity:2,rarity:"common",pol:{act:1,disc:1},conceptFamily:"price-sleep",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170366,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The cat that moved in next door",desc:"A small, faintly absurd emblem of neglect — even the animal has chosen the house where someone is home.",example:"(the cat is theirs. The cat lives at number twelve now. The cat has a point.)",intensity:1,rarity:"uncommon",pol:{mood:-1},conceptFamily:"price-cat",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170367,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Everything, and they'd pay it twice",desc:"The price is total — home, health, people — and they have looked at it squarely and would sign again.",example:"I know what it cost. I was there when it cost it. I'd do it again tomorrow.",intensity:5,rarity:"signature",pol:{disc:1,ego:1},conceptFamily:"price-everything",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170368,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"Someone else's whole life, spent for them",desc:"The competing claim is a person who gave up their own chances so this goal could exist, and who is watching.",example:"(Mum didn't go to college. So they have to finish. That's the arithmetic.)",intensity:5,rarity:"distinctive",pol:{warm:1,disc:1},conceptFamily:"claim-inherited-sacrifice",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170369,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"A promise to a dying person",desc:"The competing claim is a vow made at a bedside, which the goal quietly contradicts, and nobody living knows it was made.",example:"(said 'I will' at the hospice. The thing they want now would mean 'I didn't'.)",intensity:5,rarity:"signature",pol:{hon:1,mood:-1},conceptFamily:"claim-deathbed-promise",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170370,section:"Goals & Stakes",category:"The Price & The Competing Claim",trait:"The old friends' good opinion",desc:"Succeeding would look, to the people who knew them first, like leaving — and their good opinion is the one that still counts.",example:"(the promotion means the suit. The suit means the pub goes quiet when they walk in.)",intensity:3,rarity:"uncommon",pol:{agr:1,ego:-1},conceptFamily:"price-old-friends",behaviorFunction:"connect",reviewStatus:"reviewed"},

// ================================================================ ORDINARY TEXTURE
// ---- Preferences & Small Pleasures
{id:170169,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"The first coffee, outside, whatever the weather",desc:"A daily minute alone with a cup on a step or a doorway, non-negotiable and unremarkable.",example:"(rain. Coat over pyjamas. Cup. Two minutes. Then the day.)",intensity:2,rarity:"common",pol:{},conceptFamily:"texture-coffee",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170170,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"Crossword before anyone's up",desc:"A small private hour of puzzle and quiet, guarded gently.",example:"(the paper is folded to the grid before the kettle's on)",intensity:2,rarity:"common",pol:{cur:1},conceptFamily:"texture-crossword",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170171,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"Cheap biscuits over good ones",desc:"A firm, unembarrassed preference for the plain, the ordinary, the childhood version.",example:"Don't want the posh ones. Want the pink wafers.",intensity:1,rarity:"common",pol:{},conceptFamily:"texture-taste",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170172,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"The same three albums since twenty",desc:"A tiny, fixed musical world, returned to weekly with undimmed pleasure.",example:"(you could set a calendar by the Sunday record)",intensity:2,rarity:"uncommon",pol:{cur:-1},conceptFamily:"texture-music",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170173,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"A bath, a book, the door locked",desc:"One weekly hour of complete privacy, planned for and defended.",example:"Thursday, eight to nine. Fire, flood, or the Second Coming. Otherwise no.",intensity:3,rarity:"common",pol:{},conceptFamily:"texture-privacy",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170174,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"Collects one small pointless thing",desc:"Matchboxes, tram tickets, a particular blue glass — a modest, joyful, decades-long accumulation.",example:"(the shelf has two hundred of them. Each has a story. None is worth anything.)",intensity:2,rarity:"uncommon",pol:{cur:1},conceptFamily:"texture-collection",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170175,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"Loves a weather forecast",desc:"Genuine, daily, ordinary delight in tomorrow's sky, discussed at length with anyone.",example:"Fronts coming in Thursday. Proper front. Wait till you see it.",intensity:2,rarity:"common",pol:{pos:1},conceptFamily:"texture-weather",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170176,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"Always the window seat",desc:"A small, consistent, gently enforced preference on every bus, train and plane.",example:"(swapped, politely, four times this year. Always gets it.)",intensity:1,rarity:"common",pol:{},conceptFamily:"texture-seat",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170177,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"Eats the crust first",desc:"A lifelong, unexplained small ritual with food that everyone close to them can predict.",example:"(the crusts go, then the middle. Has always been so.)",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"texture-food-ritual",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170178,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"A particular bench, a particular view",desc:"One place in town that is theirs, visited without purpose, often.",example:"(twenty minutes on the same bench most days. Doing nothing. Doing it well.)",intensity:2,rarity:"distinctive",pol:{act:-1},conceptFamily:"texture-place",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170179,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"The good pen",desc:"One object — a pen, a knife, a mug — that is theirs alone and quietly precious.",example:"(you may borrow anything in the house. Not that.)",intensity:2,rarity:"common",pol:{},conceptFamily:"texture-object",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170180,section:"Ordinary Texture",category:"Preferences & Small Pleasures",trait:"Watches the same film every Christmas",desc:"A single fixed annual pleasure, unironic, protected from anyone's suggestion of something new.",example:"We're not watching something new. We've never watched something new. Sit down.",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"texture-annual",behaviorFunction:"soothe",reviewStatus:"reviewed"},

// ---- Routines
{id:170181,section:"Ordinary Texture",category:"Routines",trait:"Shoes off at the door, always",desc:"A small domestic rule, enforced kindly on everyone including the plumber.",example:"(there's a basket. There are spare slippers. This is a slippers house.)",intensity:2,rarity:"common",pol:{disc:1},conceptFamily:"routine-shoes",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170182,section:"Ordinary Texture",category:"Routines",trait:"Sunday call to the sister",desc:"A weekly phone call at a fixed hour, kept through decades, arguments and time zones.",example:"(six o'clock. Every Sunday. Sometimes forty minutes. Sometimes 'you all right? Good.')",intensity:2,rarity:"common",pol:{warm:1,disc:1},conceptFamily:"routine-call",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170183,section:"Ordinary Texture",category:"Routines",trait:"Walks the same loop at dusk",desc:"An evening circuit — same streets, same order — done in all weathers and thought of as the day's hinge.",example:"(the dog died three years ago. The walk continues.)",intensity:2,rarity:"uncommon",pol:{disc:1,act:1},conceptFamily:"routine-walk",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170184,section:"Ordinary Texture",category:"Routines",trait:"Lays out tomorrow's clothes",desc:"A quiet nightly preparation that makes mornings possible.",example:"(the chair, the shirt, the socks on top, in that order, every night)",intensity:2,rarity:"common",pol:{disc:1},conceptFamily:"routine-clothes",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170185,section:"Ordinary Texture",category:"Routines",trait:"Friday fish, no exceptions",desc:"A fixed weekly meal whose origin nobody remembers and whose observance nobody questions.",example:"It's Friday. — So? — So it's fish.",intensity:1,rarity:"common",pol:{},conceptFamily:"routine-meal",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170186,section:"Ordinary Texture",category:"Routines",trait:"Checks the locks twice",desc:"A modest nightly ritual of doors and windows, not anxious, just done.",example:"(front, back, front again. Then bed. Then sleep, easily.)",intensity:1,rarity:"common",pol:{disc:1},conceptFamily:"routine-locks",behaviorFunction:"control",reviewStatus:"reviewed"},
{id:170187,section:"Ordinary Texture",category:"Routines",trait:"The allotment on Saturday morning",desc:"Half a day a week given to soil and quiet, whatever else is happening.",example:"(the wedding is at two. The beans are at eight. Both will be attended.)",intensity:3,rarity:"uncommon",pol:{disc:1},conceptFamily:"routine-garden",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170188,section:"Ordinary Texture",category:"Routines",trait:"Writes the day down before sleep",desc:"Three lines in a notebook every night — not a diary, a ledger of having been here.",example:"(the notebooks go back to 1994. Nobody has read them. That's not what they're for.)",intensity:2,rarity:"distinctive",pol:{disc:1,emo:1},conceptFamily:"routine-journal",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170189,section:"Ordinary Texture",category:"Routines",trait:"Tea at four, whoever's there",desc:"A daily pause with a pot, offered to anyone in range and taken alone if nobody is.",example:"(the clock strikes. The kettle goes on. It's simply what four o'clock is.)",intensity:2,rarity:"common",pol:{warm:1},conceptFamily:"routine-tea",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170190,section:"Ordinary Texture",category:"Routines",trait:"Cleans the boots on Sunday night",desc:"An unhurried, unremarkable weekly job, done with the radio on, that closes the week.",example:"(newspaper on the table, brush, polish, cloth. Twenty minutes. Week over.)",intensity:1,rarity:"uncommon",pol:{disc:1},conceptFamily:"routine-boots",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170191,section:"Ordinary Texture",category:"Routines",trait:"Same barber, same chair, twenty years",desc:"A small standing loyalty to one shop and one person, kept past every reason to change.",example:"He's not the best. He's mine. Been mine since school.",intensity:2,rarity:"common",pol:{agr:1},conceptFamily:"routine-barber",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170192,section:"Ordinary Texture",category:"Routines",trait:"Bins out the night before, in the dark",desc:"A tiny, reliable domestic act done late, alone, that is somehow the last word of the week.",example:"(ten past eleven. The bins. Then and only then, the week is over.)",intensity:1,rarity:"common",pol:{disc:1},conceptFamily:"routine-bins",behaviorFunction:"control",reviewStatus:"reviewed"},

// ---- Affiliations
{id:170193,section:"Ordinary Texture",category:"Affiliations",trait:"The pub quiz team, undefeated in geography",desc:"A weekly team of the same four, one of whom is them, with a known specialism and a running joke.",example:"(Tuesdays. Table by the door. They do capitals. Never miss a capital.)",intensity:2,rarity:"common",pol:{warm:1},conceptFamily:"affiliation-quiz",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170194,section:"Ordinary Texture",category:"Affiliations",trait:"Treasurer of something small",desc:"Holds a modest office — the allotment society, the parish hall — with more seriousness than it strictly needs.",example:"(the accounts of the bowls club are immaculate and presented annually to eleven people)",intensity:2,rarity:"common",pol:{disc:1},conceptFamily:"affiliation-office",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170195,section:"Ordinary Texture",category:"Affiliations",trait:"Supports the losing club, loudly",desc:"A lifelong allegiance to a team that rarely wins, worn as a moral position.",example:"Twenty-two years without a trophy. Wouldn't swap it. Couldn't.",intensity:3,rarity:"common",pol:{agr:1,pos:-1},conceptFamily:"affiliation-club",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170196,section:"Ordinary Texture",category:"Affiliations",trait:"Sings in a choir, badly, gladly",desc:"Weekly membership of a group that makes a noise together, with no ambition beyond the making.",example:"(alto. Approximately. Loves every Wednesday.)",intensity:2,rarity:"uncommon",pol:{warm:1,pos:1},conceptFamily:"affiliation-choir",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170197,section:"Ordinary Texture",category:"Affiliations",trait:"The union card, kept",desc:"A membership held since the first job, paid every month, not always used, never let lapse.",example:"Still paying in. — Why? — Because you don't stop paying in.",intensity:2,rarity:"uncommon",pol:{agr:1,rebel:1},conceptFamily:"affiliation-union",behaviorFunction:"protect",reviewStatus:"reviewed"},
{id:170198,section:"Ordinary Texture",category:"Affiliations",trait:"Regular at one cafe",desc:"A known face at a single counter — order remembered, seat implied, news exchanged.",example:"The usual? — The usual. — (nobody has said what the usual is in nine years)",intensity:1,rarity:"common",pol:{warm:1},conceptFamily:"affiliation-cafe",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170199,section:"Ordinary Texture",category:"Affiliations",trait:"Volunteers on the second Saturday",desc:"A monthly shift somewhere — the foodbank, the litter pick, the museum desk — done without mention.",example:"(unavailable on the second Saturday. Has been for eleven years. Doesn't say why.)",intensity:2,rarity:"common",pol:{warm:1,agr:1},conceptFamily:"affiliation-volunteer",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170200,section:"Ordinary Texture",category:"Affiliations",trait:"Still goes to the reunion",desc:"An annual gathering of people who knew them at nineteen, attended faithfully, enjoyed ambivalently.",example:"(hates it. Books it in January. Wouldn't miss it.)",intensity:2,rarity:"uncommon",pol:{agr:1},conceptFamily:"affiliation-reunion",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170201,section:"Ordinary Texture",category:"Affiliations",trait:"The card school on Thursdays",desc:"A standing game with the same people, small stakes, large loyalty.",example:"(has lost forty pounds to the same three people over twenty years and would not give it up for anything)",intensity:2,rarity:"common",pol:{warm:1},conceptFamily:"affiliation-cards",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170202,section:"Ordinary Texture",category:"Affiliations",trait:"Church at Easter and Christmas, no more",desc:"A loose, sincere, twice-yearly belonging, held without doctrine and without apology.",example:"Not religious. Go twice a year. Both things are true.",intensity:1,rarity:"common",pol:{},conceptFamily:"affiliation-church",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170203,section:"Ordinary Texture",category:"Affiliations",trait:"On the residents' committee, reluctantly",desc:"Pressed into a local role nobody else would take, and now quietly good at it.",example:"I only came to complain about the bins. Now I'm the chair. Nobody tell me how.",intensity:2,rarity:"uncommon",pol:{agr:1,disc:1},conceptFamily:"affiliation-committee",behaviorFunction:"provide",reviewStatus:"reviewed"},
{id:170204,section:"Ordinary Texture",category:"Affiliations",trait:"The old regiment, once a year",desc:"A single annual dinner with people who share something that is not discussed, and a standing toast.",example:"(the third Friday in November. A suit. A silence. A drink to names.)",intensity:3,rarity:"distinctive",pol:{agr:1,emo:-1},conceptFamily:"affiliation-regiment",behaviorFunction:"connect",reviewStatus:"reviewed",worldTags:["military"]},

// ---- Practised Badly
{id:170205,section:"Ordinary Texture",category:"Practised Badly",trait:"The guitar with three chords",desc:"Twenty years of enthusiastic, unimproving playing of the same songs, and no wish to get better.",example:"(plays the same four songs at every party. Everyone knows the words. Nobody minds.)",intensity:2,rarity:"common",pol:{pos:1},conceptFamily:"badly-guitar",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170206,section:"Ordinary Texture",category:"Practised Badly",trait:"Runs, slowly, and talks about it",desc:"A cheerful, mediocre, persistent runner whose times have not moved in a decade.",example:"Did a 5K. — Time? — Not the point. Did a 5K.",intensity:2,rarity:"common",pol:{act:1,pos:1},conceptFamily:"badly-running",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170207,section:"Ordinary Texture",category:"Practised Badly",trait:"Paints, and gives the paintings away",desc:"Watercolours of variable quality, produced steadily and pressed on friends and relatives with pride.",example:"(everyone who knows them owns at least one boat)",intensity:2,rarity:"uncommon",pol:{warm:1},conceptFamily:"badly-painting",behaviorFunction:"connect",reviewStatus:"reviewed"},
{id:170208,section:"Ordinary Texture",category:"Practised Badly",trait:"A language learned to page forty",desc:"Restarts the same beginners' course every couple of years, reaching the same chapter, with undiminished hope.",example:"Doing Italian again. — Again? — Properly this time. (page forty.)",intensity:1,rarity:"common",pol:{cur:1,disc:-1},conceptFamily:"badly-language",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170209,section:"Ordinary Texture",category:"Practised Badly",trait:"Cooks one thing, dramatically",desc:"A single signature dish, made with enormous ceremony and middling results, served often.",example:"(the chilli. The famous chilli. It's fine. It's a whole evening.)",intensity:2,rarity:"common",pol:{vol:1},conceptFamily:"badly-cooking",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170210,section:"Ordinary Texture",category:"Practised Badly",trait:"Fishes, catches nothing, goes again",desc:"A pursuit kept up for the sitting, not the catching, with a straight face about the results.",example:"(eleven years. Two fish. Both small. Wouldn't change a thing.)",intensity:2,rarity:"uncommon",pol:{act:-1,pos:1},conceptFamily:"badly-fishing",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170211,section:"Ordinary Texture",category:"Practised Badly",trait:"Dances like nobody's told them",desc:"Terrible, joyful, unselfconscious dancing at every wedding, every time.",example:"(the first on the floor and the worst on it, and nobody would have it otherwise)",intensity:3,rarity:"common",pol:{pos:1,ego:1},conceptFamily:"badly-dancing",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170212,section:"Ordinary Texture",category:"Practised Badly",trait:"Whistles, out of tune, all day",desc:"A constant, tuneless, contented accompaniment to everything they do.",example:"(you can find them anywhere in the building by it)",intensity:2,rarity:"common",pol:{pos:1},conceptFamily:"badly-whistling",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170213,section:"Ordinary Texture",category:"Practised Badly",trait:"Grows tomatoes that never ripen",desc:"An annual, doomed, faithfully repeated horticultural project.",example:"This is the year. — You said that last year. — This is the year.",intensity:1,rarity:"uncommon",pol:{pos:1},conceptFamily:"badly-tomatoes",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170214,section:"Ordinary Texture",category:"Practised Badly",trait:"Writes the novel, on and off, forever",desc:"A book in progress for fifteen years, mentioned rarely, worked on in bursts, never expected to finish.",example:"(chapter nine. Has been chapter nine since 2016. Chapter nine is going well.)",intensity:2,rarity:"distinctive",pol:{cur:1,disc:-1},conceptFamily:"badly-novel",behaviorFunction:"soothe",reviewStatus:"reviewed"},
{id:170215,section:"Ordinary Texture",category:"Practised Badly",trait:"Does magic tricks, and the tricks show",desc:"A small repertoire of visible sleight-of-hand performed for children who can see exactly how it works.",example:"(the coin is in the other hand. Everyone can see it's in the other hand. Applause anyway.)",intensity:2,rarity:"uncommon",pol:{warm:1},conceptFamily:"badly-magic",behaviorFunction:"perform",reviewStatus:"reviewed"},
{id:170216,section:"Ordinary Texture",category:"Practised Badly",trait:"Cycles everywhere, wobbling",desc:"An adult cyclist of thirty years' standing who has never quite got the hang of it and goes anyway.",example:"(the bike is ancient. The technique is worse. The commute is done daily.)",intensity:2,rarity:"common",pol:{act:1},conceptFamily:"badly-cycling",behaviorFunction:"soothe",reviewStatus:"reviewed"},

// ================================================================ RECOVERY & REPAIR
// ---- Apology
{id:170217,section:"Recovery & Repair",category:"Apology",trait:"Says sorry once, exactly, and means it",desc:"A single plain apology with no hedging and no repetition, and then it is over for them.",example:"I was wrong to say that. I'm sorry. — (and nothing further; it's complete)",intensity:3,rarity:"distinctive",pol:{hon:1,ego:1},conceptFamily:"repair-clean-apology",behaviorFunction:"repair",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170218,section:"Recovery & Repair",category:"Apology",trait:"Apologises in writing, never aloud",desc:"Cannot say it face to face; the note, the card, the long message arrives the next day and says everything.",example:"(the envelope on the table in the morning. Four pages. Every word right.)",intensity:3,rarity:"uncommon",pol:{emo:-1,hon:1},conceptFamily:"repair-written-apology",behaviorFunction:"repair",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170219,section:"Recovery & Repair",category:"Apology",trait:"Sorry for the tone, not the point",desc:"Concedes the manner readily and never the substance; the apology is real and the position is unmoved.",example:"I shouldn't have shouted. I was right, but I shouldn't have shouted.",intensity:3,rarity:"common",pol:{asrt:1,agr:-1},conceptFamily:"repair-tone-apology",behaviorFunction:"repair",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170220,section:"Recovery & Repair",category:"Apology",trait:"Over-apologises until it's a second problem",desc:"The sorry keeps coming, in escalating forms, until the injured party has to comfort them.",example:"I'm so sorry. I'm really — I'm so — — It's fine. — It's NOT fine, I'm— — It's fine. Stop.",intensity:4,rarity:"common",pol:{ego:-1,emo:1},conceptFamily:"repair-over-apology",behaviorFunction:"soothe",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170221,section:"Recovery & Repair",category:"Apology",trait:"Apologises to the wrong person first",desc:"Says sorry to everyone around the injury — the bystander, the host, the child — before the person actually hurt.",example:"(has apologised to the waiter, the friend and the dog. Not yet to the spouse.)",intensity:2,rarity:"distinctive",pol:{emo:-1},conceptFamily:"repair-misdirected",behaviorFunction:"avoid",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170222,section:"Recovery & Repair",category:"Apology",trait:"Sorry, with a full account of why",desc:"The apology comes with the complete explanation — context, causes, what they were feeling — whether wanted or not.",example:"I'm sorry, and I want you to understand what was going on for me, because at about four o'clock—",intensity:3,rarity:"common",pol:{vol:1,hon:1},conceptFamily:"repair-explained-apology",behaviorFunction:"repair",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170223,section:"Recovery & Repair",category:"Apology",trait:"Apologises by asking how you are",desc:"Never says the word; the next day's unusual, careful, specific attention is the apology.",example:"(has never said sorry in their life. Brought soup. Asked about the meeting. Remembered the name.)",intensity:2,rarity:"uncommon",pol:{emo:-1,warm:1},conceptFamily:"repair-attention-apology",behaviorFunction:"repair",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170224,section:"Recovery & Repair",category:"Apology",trait:"Says sorry before the other person's finished",desc:"Concedes so fast the grievance can't be fully aired, which leaves it half-alive.",example:"— and then you said — — Sorry. Yes. Sorry. — I hadn't got to the bit that—",intensity:3,rarity:"uncommon",pol:{agr:1,asrt:-1},conceptFamily:"repair-premature",behaviorFunction:"avoid",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170225,section:"Recovery & Repair",category:"Apology",trait:"Takes a week, then does it properly",desc:"Nothing for days — then a considered, complete apology that shows they've thought about it the whole time.",example:"(silence till Thursday. Then: 'I've been thinking about Sunday. Here's what I got wrong.')",intensity:3,rarity:"distinctive",pol:{disc:1,hon:1},conceptFamily:"repair-delayed-apology",behaviorFunction:"repair",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170226,section:"Recovery & Repair",category:"Apology",trait:"Never apologises, always makes it right",desc:"The word is not in them; the deed — the replaced thing, the fixed thing, the changed behaviour — always is.",example:"(the broken gate is rebuilt by dawn. No note. Better than the old one.)",intensity:4,rarity:"signature",pol:{emo:-1,disc:1},conceptFamily:"repair-deed-not-word",behaviorFunction:"repair",frequency:2,visibility:4,persistence:2,narrativeSalience:4,reviewStatus:"reviewed"},

// ---- Restitution & Practical Care
{id:170227,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Turns up with food",desc:"After any rupture, arrives at the door with a dish; the dish is the whole conversation.",example:"(lasagne. On the step. Text: 'oven, 180, forty minutes.' That's the peace treaty.)",intensity:3,rarity:"common",pol:{warm:1,emo:-1},conceptFamily:"repair-food",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170228,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Pays it back with interest, unasked",desc:"Whatever was taken, broken or cost is replaced at more than its value, quietly and promptly.",example:"(borrowed twenty. Returned forty, in an envelope, with no note.)",intensity:3,rarity:"uncommon",pol:{hon:1,disc:1},conceptFamily:"repair-overpay",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170229,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Fixes something else entirely",desc:"Can't address the actual wrong; mends the fence, services the car, sorts the paperwork instead.",example:"(they argued about the wedding. The gutters have never been cleaner.)",intensity:3,rarity:"distinctive",pol:{emo:-1,disc:1},conceptFamily:"repair-displaced",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170230,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Does the chore they've refused for years",desc:"A silent, unmistakable gesture — the thing they'd always said no to, done, once, the morning after.",example:"(the loft. Cleared. By seven a.m. Not mentioned.)",intensity:3,rarity:"uncommon",pol:{agr:1,emo:-1},conceptFamily:"repair-chore",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170231,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Drives them wherever, for a month",desc:"Restitution as service: makes themselves useful, daily, until the debt feels paid to both of them.",example:"I'll pick you up. Every day. Till you tell me to stop. — That's not— — Every day.",intensity:4,rarity:"distinctive",pol:{warm:1,disc:1},conceptFamily:"repair-service",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170232,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Buys something too expensive",desc:"Apology by object — the gift arrives out of proportion to the offence and everyone knows what it means.",example:"(the flowers cost more than the dinner they ruined. That's the point.)",intensity:3,rarity:"common",pol:{ego:-1},conceptFamily:"repair-gift",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170233,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Sits with them, says nothing",desc:"After the damage, simply stays — in the room, on the step, in the car — for as long as it takes.",example:"(two hours on the bench. Not a word. It was enough.)",intensity:3,rarity:"distinctive",pol:{warm:1,vol:-1},conceptFamily:"repair-presence",behaviorFunction:"soothe",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170234,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Tells everyone it was their fault",desc:"Corrects the record publicly — in the group, at work, with the family — taking the blame in front of witnesses.",example:"Just so everyone knows: that was me. Not her. Me.",intensity:4,rarity:"uncommon",pol:{hon:1,ego:1},conceptFamily:"repair-public-blame",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170235,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Makes the phone call they dread",desc:"Restitution means doing the hard practical thing — ringing the bank, the school, the ex — on the other person's behalf.",example:"I'll ring them. It's my mess. Give me the number.",intensity:3,rarity:"uncommon",pol:{disc:1,asrt:1},conceptFamily:"repair-hard-call",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170236,section:"Recovery & Repair",category:"Restitution & Practical Care",trait:"Rebuilds it exactly as it was",desc:"Whatever got broken is restored to the last detail, as if the restoration could unmake the breaking.",example:"(the same mug, found online, six weeks of searching. Same chip, even. Almost.)",intensity:3,rarity:"distinctive",pol:{disc:1,emo:1},conceptFamily:"repair-restore",behaviorFunction:"repair",frequency:2,visibility:3,persistence:3,narrativeSalience:4,reviewStatus:"reviewed"},

// ---- Avoidance & Humour
{id:170237,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Acts as if nothing happened",desc:"The next morning is entirely ordinary — tea, weather, plans — and the fight is never referred to again by them.",example:"Morning! Lovely out. — (last night is not available for discussion)",intensity:3,rarity:"common",pol:{emo:-1},conceptFamily:"repair-erase",behaviorFunction:"avoid",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170238,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Jokes about it too soon",desc:"Reaches for the funny version while the wound is still open, and means it kindly.",example:"So that went well. — (too early. Much too early. They know. They did it anyway.)",intensity:3,rarity:"common",pol:{emo:-1,pos:1},conceptFamily:"repair-early-joke",behaviorFunction:"avoid",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170239,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Goes quiet for three days",desc:"Disappears into silence — not sulking, exactly, more a full retreat — and re-emerges as if refreshed.",example:"(no calls. No messages. Thursday: 'Hey. Fancy a walk?')",intensity:3,rarity:"uncommon",pol:{emo:-1,act:-1},conceptFamily:"repair-retreat",behaviorFunction:"avoid",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170240,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Makes it a story by the weekend",desc:"Within days the row has become an anecdote, told with both parties as characters, and the telling is the mending.",example:"So she's standing there with the colander— — I did NOT— — she's standing there with the colander—",intensity:3,rarity:"distinctive",pol:{pos:1,vol:1},conceptFamily:"repair-anecdote",behaviorFunction:"repair",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170241,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Changes the subject to the dog",desc:"Any approach to the sore point is redirected, warmly and reliably, to something safe and shared.",example:"About yesterday— — Has he been out? He hasn't been out. Come on, boy.",intensity:2,rarity:"common",pol:{emo:-1,warm:1},conceptFamily:"repair-redirect",behaviorFunction:"avoid",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170242,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Leaves the country, briefly",desc:"After a serious rupture, a sudden, unplanned trip; returns tanned, calm, and ready to talk.",example:"(three days. Somewhere with a beach. Back with a plan and a sunburn.)",intensity:4,rarity:"uncommon",pol:{rebel:1,emo:-1},conceptFamily:"repair-flight",behaviorFunction:"avoid",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170243,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Self-mockery as the white flag",desc:"Comes back into the room already doing an impression of themselves at their worst, and it works.",example:"(in a silly voice) 'I'm never speaking to you AGAIN.' — Right, idiot. Sit down.",intensity:3,rarity:"distinctive",pol:{ego:-1,pos:1},conceptFamily:"repair-self-mock",behaviorFunction:"repair",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170244,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Waits for the other person to start",desc:"Will never raise it, ever; is entirely ready to talk the moment someone else does.",example:"(fully prepared. Fully willing. Will die before opening the subject.)",intensity:2,rarity:"common",pol:{asrt:-1},conceptFamily:"repair-wait",behaviorFunction:"avoid",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170245,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Busy, suddenly, for a fortnight",desc:"Work, errands and prior commitments multiply until there is no evening in which it could come up.",example:"Can't tonight. Or tomorrow. Or — actually the week's bad. Next week's bad too.",intensity:3,rarity:"uncommon",pol:{emo:-1,disc:1},conceptFamily:"repair-busy",behaviorFunction:"avoid",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed"},
{id:170246,section:"Recovery & Repair",category:"Avoidance & Humour",trait:"Sends a meme, means 'I love you'",desc:"Contact is re-established through something small, silly and shared — the reply is the reconciliation.",example:"(a picture of a goose in a hat. Reply: a goose in a smaller hat. Sorted.)",intensity:2,rarity:"distinctive",pol:{warm:1,emo:-1},conceptFamily:"repair-meme",behaviorFunction:"repair",frequency:3,visibility:3,persistence:2,narrativeSalience:3,reviewStatus:"reviewed",worldTags:["modern","online"]},

// ---- Changed Boundaries & Failed Repair
{id:170247,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Forgives, and never lends again",desc:"The relationship continues, warmly — with one door permanently and politely closed.",example:"Course we're fine. — Can I borrow— — No. We're fine, though.",intensity:3,rarity:"common",pol:{warm:1,disc:1},conceptFamily:"repair-forgive-with-limit",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170248,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Says what will and won't be tolerated, once",desc:"After the rupture, one plain statement of the new terms, delivered without heat and not repeated.",example:"That can't happen again. If it does, I'll go. That's all. Pass the salt.",intensity:4,rarity:"distinctive",pol:{asrt:1,hon:1},conceptFamily:"repair-terms",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170249,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Stays, and keeps score",desc:"The repair is accepted on the surface and the offence is filed, permanently, for use.",example:"(fine. Apparently fine. Brought it up at the wedding four years later.)",intensity:3,rarity:"common",pol:{agr:-1,emo:-1},conceptFamily:"repair-ledger",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170250,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Moves the conversation to public places",desc:"Still sees them — but only in company, in restaurants, at events; the private register is closed.",example:"Lunch with everyone, lovely. Just us? Not yet. Maybe not.",intensity:3,rarity:"uncommon",pol:{warm:-1,disc:1},conceptFamily:"repair-public-only",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170251,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Tried twice, then stopped trying",desc:"Made two honest attempts to mend it; after the second failed, let it go without bitterness and without a third.",example:"I rang. I wrote. That's what I had. If she wants it, she knows where I am.",intensity:3,rarity:"distinctive",pol:{disc:1,emo:-1},conceptFamily:"repair-two-attempts",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170252,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Civil at the funeral, nowhere else",desc:"An estrangement maintained with perfect manners at the unavoidable occasions and total silence between them.",example:"(a nod across the grave. A handshake. Then another decade.)",intensity:4,rarity:"uncommon",pol:{man:1,warm:-1},conceptFamily:"repair-civil-only",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170253,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Accepts the apology, not the person",desc:"Says the right things when sorry is offered, and quietly never lets them back to where they were.",example:"Thank you. I appreciate that. — (and nothing changes, ever, and both of them know it)",intensity:3,rarity:"distinctive",pol:{man:1,emo:-1},conceptFamily:"repair-accept-not-restore",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170254,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Repairs it every time, worse each time",desc:"The same rupture, the same reconciliation, on a loop that everyone around them can see is degrading.",example:"(the fifth 'we've sorted it'. It's held for shorter each time.)",intensity:4,rarity:"common",pol:{mood:-1,disc:-1},conceptFamily:"repair-loop",behaviorFunction:"soothe",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170255,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Walks away clean, for good",desc:"Ends it entirely and without drama — no last word, no door left ajar — and does not look back.",example:"(one calm conversation. Then never again. Not angry. Just gone.)",intensity:5,rarity:"signature",pol:{disc:1,warm:-1},conceptFamily:"repair-clean-exit",behaviorFunction:"protect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170256,section:"Recovery & Repair",category:"Changed Boundaries & Failed Repair",trait:"Lets the children be the bridge",desc:"Direct repair failed; contact continues entirely through a third party, by unspoken agreement.",example:"(neither has spoken in six years. Both are at every school play. They sit two rows apart.)",intensity:3,rarity:"uncommon",pol:{warm:1,emo:-1},conceptFamily:"repair-proxy",behaviorFunction:"connect",frequency:2,visibility:2,persistence:5,narrativeSalience:4,reviewStatus:"reviewed"},

// ================================================================ CONTRADICTION FUNCTIONS
// ---- Protective Hypocrisy
{id:170257,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Preaches honesty, lies to keep them safe",desc:"The contradiction serves a person: the rule is truth, the exception is anyone who'd be hurt by it.",example:"Always tell the truth. — Did you tell Mum about the biopsy? — ...Not yet.",intensity:3,rarity:"common",pol:{hon:1,warm:1},conceptFamily:"contradiction-protective-lie",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed",conditions:["intimacy"]},
{id:170258,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Hates gossip, briefs the family",desc:"Contemptuous of talk about others; keeps their own people informed of every threat, which is the same thing done for love.",example:"I don't gossip. — You told Nan about the neighbour. — That's not gossip, that's a warning.",intensity:2,rarity:"common",pol:{warm:1,hon:-1},conceptFamily:"contradiction-protective-gossip",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},
{id:170259,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Frugal to the bone, extravagant for the child",desc:"Every personal expense scrutinised; anything for the dependent is bought without a second look.",example:"(darns their own socks. The kid has the new boots. Both of those are the same rule.)",intensity:3,rarity:"uncommon",pol:{disc:1,warm:1},conceptFamily:"contradiction-frugal-generous",behaviorFunction:"provide",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed",conditions:["dependent"]},
{id:170260,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Rules for the team, none for the sick",desc:"A strict manager who quietly breaks every policy the moment someone is ill, grieving or scared.",example:"(no exceptions on lateness. Sent the grieving one home for a month on full pay. No exceptions.)",intensity:4,rarity:"distinctive",pol:{disc:1,warm:1},conceptFamily:"contradiction-strict-merciful",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed",conditions:["work"]},
{id:170261,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Non-violent, would kill for them",desc:"Pacifist by conviction and unmistakably not, where one specific person's safety is concerned.",example:"I don't believe in it. — And if someone hurt her? — Then I'd stop believing.",intensity:5,rarity:"distinctive",pol:{agr:1,warm:1},conceptFamily:"contradiction-pacifist-protector",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed",conditions:["threat"]},
{id:170262,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Champions independence, does everything for them",desc:"Loudly for people standing on their own feet; quietly does the washing, the forms, the driving, for the one they love.",example:"She needs to learn to cope. — (has done her tax return. Again.)",intensity:3,rarity:"common",pol:{warm:1,hon:-1},conceptFamily:"contradiction-independence-caretaking",behaviorFunction:"provide",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},
{id:170263,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Says 'no secrets', keeps the big one",desc:"A household rule of total openness maintained on top of one enormous concealment, held for everyone's sake.",example:"We don't do secrets in this family. — (the adoption, the debt, the first marriage: none of them known)",intensity:4,rarity:"uncommon",pol:{hon:-1,warm:1},conceptFamily:"contradiction-no-secrets",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},
{id:170264,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Despises favouritism, has a favourite",desc:"Scrupulously fair in every visible way, with one person who gets more, always, and everyone knows it.",example:"I treat them all the same. — (the youngest has never been told no)",intensity:3,rarity:"common",pol:{warm:1,hon:-1},conceptFamily:"contradiction-favourite",behaviorFunction:"provide",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},
{id:170265,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Tough on everyone, soft on the broken",desc:"Demanding, blunt, unsentimental — and gentle to the point of tenderness with anyone visibly at the end of their rope.",example:"(tore a strip off the whole crew. Sat with the one who was crying until it was dark.)",intensity:4,rarity:"distinctive",pol:{agr:-1,warm:1},conceptFamily:"contradiction-tough-tender",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},
{id:170266,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Lectures on health, hides their own",desc:"Nags everyone about check-ups and sleep while concealing a diagnosis, to spare them.",example:"Have you booked the appointment? — Have YOU? — That's different.",intensity:4,rarity:"uncommon",pol:{hon:-1,warm:1},conceptFamily:"contradiction-health-concealed",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},
{id:170267,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Anti-charity, pays the neighbour's rent",desc:"Publicly scornful of handouts; privately keeps three households afloat and would deny it under oath.",example:"People should stand on their own feet. — (the envelope through the door on the first of the month)",intensity:4,rarity:"distinctive",pol:{warm:1,hon:-1},conceptFamily:"contradiction-secret-generosity",behaviorFunction:"provide",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},
{id:170268,section:"Contradiction Functions",category:"Protective Hypocrisy",trait:"Tells them to leave, keeps the room ready",desc:"Says the hard, true thing — go, don't come back — and maintains the bed, the key, the light in the window regardless.",example:"I meant it. He should go. — The room's made up. — Of course the room's made up.",intensity:5,rarity:"signature",pol:{warm:1,hon:1},conceptFamily:"contradiction-go-stay",behaviorFunction:"protect",frequency:3,visibility:2,persistence:4,narrativeSalience:5,reviewStatus:"reviewed"},

// ---- Aspirational Values
{id:170269,section:"Contradiction Functions",category:"Aspirational Values",trait:"Believes in patience, has none",desc:"Holds calm as the highest virtue and is visibly, constantly, apologetically impatient — the value is the goal, not the state.",example:"Patience is everything. — You've checked your watch four times. — I KNOW.",intensity:3,rarity:"common",pol:{disc:-1,pos:1},conceptFamily:"contradiction-aspirational-patience",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170270,section:"Contradiction Functions",category:"Aspirational Values",trait:"Preaches simplicity from a cluttered house",desc:"Genuinely wants less; is surrounded by more; the sermon is aimed at themselves and everyone can tell.",example:"We need to live with less. — (the hall has eleven coats. Four are theirs.)",intensity:2,rarity:"common",pol:{disc:-1},conceptFamily:"contradiction-aspirational-simplicity",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170271,section:"Contradiction Functions",category:"Aspirational Values",trait:"Values courage, and is frightened of everything",desc:"Admires bravery above all, talks about it constantly, and is scared of the phone, the dark and the dentist — and keeps trying.",example:"Be brave. Be brave. (rings the dentist. Hangs up. Rings again. Books it.)",intensity:3,rarity:"uncommon",pol:{ego:-1,pos:1},conceptFamily:"contradiction-aspirational-courage",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170272,section:"Contradiction Functions",category:"Aspirational Values",trait:"Advocates forgiveness, nurses a grudge",desc:"Sincerely believes in letting go; carries one decades-old resentment like a stone in a shoe, and knows it.",example:"Forgive and move on. — Even him? — ...I'm working on him.",intensity:3,rarity:"common",pol:{agr:1,mood:-1},conceptFamily:"contradiction-aspirational-forgiveness",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170273,section:"Contradiction Functions",category:"Aspirational Values",trait:"Talks of the present, lives in the past",desc:"Preaches mindfulness and the moment; is, at all times, twelve years ago.",example:"Be here now. — You're telling the 2012 story again. — ...Be here now.",intensity:3,rarity:"uncommon",pol:{pos:1,mood:-1},conceptFamily:"contradiction-aspirational-presence",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170274,section:"Contradiction Functions",category:"Aspirational Values",trait:"Believes in early nights, sees every dawn",desc:"The rule is bed by ten and the life is three a.m.; the rule is kept as a hope.",example:"Early night tonight. — You said that. — I'm saying it again. It's aspirational.",intensity:2,rarity:"common",pol:{disc:-1},conceptFamily:"contradiction-aspirational-sleep",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170275,section:"Contradiction Functions",category:"Aspirational Values",trait:"Preaches thrift, cannot pass a bookshop",desc:"A sincere ethic of restraint with one perfectly visible, joyfully unrestrained exception.",example:"We're cutting back. — That's six books. — Books aren't spending. Books are — they're different.",intensity:2,rarity:"uncommon",pol:{cur:1,disc:-1},conceptFamily:"contradiction-aspirational-thrift",behaviorFunction:"soothe",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170276,section:"Contradiction Functions",category:"Aspirational Values",trait:"Says people are good, trusts nobody",desc:"A sincere creed of human decency held alongside a locked door, a checked reference and a counted change.",example:"Most people are kind. — You counted the change. — Most people. Not all. Counting's free.",intensity:3,rarity:"distinctive",pol:{pos:1,warm:-1},conceptFamily:"contradiction-aspirational-trust",behaviorFunction:"protect",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170277,section:"Contradiction Functions",category:"Aspirational Values",trait:"Wants to be spontaneous, plans the spontaneity",desc:"Yearns for the unplanned and schedules it, in pen, with contingencies.",example:"Saturday we're being spontaneous. — You've written it down. — Spontaneous, ten till two.",intensity:2,rarity:"common",pol:{disc:1,cur:1},conceptFamily:"contradiction-aspirational-spontaneity",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170278,section:"Contradiction Functions",category:"Aspirational Values",trait:"Values humility, mentions it",desc:"Genuinely tries not to boast; boasts, faintly and often, about the trying.",example:"I don't like to make a thing of it. — You're making a thing of it. — I'm making a small thing of not making a thing of it.",intensity:2,rarity:"common",pol:{ego:1},conceptFamily:"contradiction-aspirational-humility",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170279,section:"Contradiction Functions",category:"Aspirational Values",trait:"Believes in rest, and can't",desc:"Preaches recovery, downtime, the sabbath — and is visibly incapable of an idle hour; the belief is what they wish for.",example:"Rest is productive. — Sit down, then. — (sits. Stands. Wipes a surface. Sits.)",intensity:3,rarity:"uncommon",pol:{act:1,disc:1},conceptFamily:"contradiction-aspirational-rest",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170280,section:"Contradiction Functions",category:"Aspirational Values",trait:"Sees the best in people, once they've left",desc:"Critical of everyone present; generous, sincere, and glowing about everyone absent — the value is real and can only be practised at a distance.",example:"(to their face: sharp. About them, later: 'she's wonderful, honestly, she is')",intensity:3,rarity:"distinctive",pol:{warm:1,agr:-1},conceptFamily:"contradiction-aspirational-charity",behaviorFunction:"perform",frequency:4,visibility:3,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},

// ---- Exceptions & Detachment
{id:170281,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Cold in the clinic, weeping in the car",desc:"Professional detachment, total and necessary, that is paid for privately afterwards.",example:"(delivered the diagnosis without a flicker. Sat in the car park for forty minutes.)",intensity:4,rarity:"distinctive",pol:{emo:-1,warm:1},conceptFamily:"contradiction-professional-detachment",behaviorFunction:"protect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["work"]},
{id:170282,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Honest with everyone but their mother",desc:"A blanket rule of candour with a single lifelong exception, maintained out of love and fear in equal parts.",example:"I tell it like it is. — And your mum? — ...Mum gets the version.",intensity:3,rarity:"common",pol:{hon:1,warm:1},conceptFamily:"contradiction-exception-parent",behaviorFunction:"protect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["intimacy"]},
{id:170283,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Polite as a weapon",desc:"Immaculate courtesy deployed strategically — to control a room, to deny an opening, to make the other person the rude one.",example:"Thank you so much for your input. (the input is dead; it died courteously)",intensity:4,rarity:"distinctive",pol:{man:1,warm:-1},conceptFamily:"contradiction-strategic-politeness",behaviorFunction:"control",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["public"]},
{id:170284,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Kind to strangers, sharp with kin",desc:"Warmth for anyone met once; the edge is saved for the people who will still be there tomorrow.",example:"(charmed the whole bus. Snapped at the sister before the door was shut.)",intensity:3,rarity:"common",pol:{warm:1,agr:-1},conceptFamily:"contradiction-exception-kin",behaviorFunction:"connect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["stranger","intimacy"]},
{id:170285,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Detached by trade, tender by accident",desc:"Trained to not feel it — police, nurse, undertaker — and ambushed by feeling at the smallest things.",example:"(unmoved by the scene. Undone by the child's shoe on the stairs.)",intensity:4,rarity:"uncommon",pol:{emo:-1,warm:1},conceptFamily:"contradiction-trained-detachment",behaviorFunction:"protect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["work"]},
{id:170286,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Conceals from shame, not from cunning",desc:"Hides the thing — the debt, the relapse, the failure — not to deceive but because the shame is unbearable to speak.",example:"It's not that I'm lying. It's that I can't say it. Those are different. Aren't they?",intensity:4,rarity:"distinctive",pol:{hon:-1,ego:-1},conceptFamily:"contradiction-shame-concealment",behaviorFunction:"protect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170287,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Rules for the world, none for the partner",desc:"Every standard they hold — punctuality, tidiness, honesty — has one person it doesn't apply to, and it's the one they chose.",example:"Late is rude. — He's forty minutes late. — He's different. He's — he's him.",intensity:3,rarity:"common",pol:{warm:1,agr:1},conceptFamily:"contradiction-exception-partner",behaviorFunction:"connect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["intimacy"]},
{id:170288,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Cheerful at the counter, bleak at home",desc:"The public warmth is a job, done well and sincerely, and it uses up everything; there is nothing left for the kitchen.",example:"(the customers love them. The family gets the silence.)",intensity:4,rarity:"uncommon",pol:{warm:1,mood:-1},conceptFamily:"contradiction-public-private",behaviorFunction:"perform",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["public","home"]},
{id:170289,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Loyal to the boss, disloyal to the firm",desc:"Devotion to one person inside an institution they would happily see burn.",example:"I'd do anything for her. — And the company? — The company can go to hell. She's not the company.",intensity:3,rarity:"distinctive",pol:{warm:1,rebel:1},conceptFamily:"contradiction-exception-boss",behaviorFunction:"connect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["work"]},
{id:170290,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Talks about feelings, never has one in the room",desc:"Fluent, articulate, generous about emotion in the abstract; goes flat and technical the moment one is actually present.",example:"It's important to sit with grief. — (someone cries) — Right. Um. Tea?",intensity:3,rarity:"uncommon",pol:{emo:-1,intel:1},conceptFamily:"contradiction-emotional-fluency",behaviorFunction:"avoid",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},
{id:170291,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Says what they think, except at work",desc:"Blunt to the point of trouble everywhere but the one place it would cost them, where they are a model of tact.",example:"(told the vicar his sermon was rubbish. Told the boss the plan was 'really interesting'.)",intensity:3,rarity:"common",pol:{hon:1,disc:1},conceptFamily:"contradiction-exception-work",behaviorFunction:"protect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed",conditions:["work"]},
{id:170292,section:"Contradiction Functions",category:"Exceptions & Detachment",trait:"Hides the good deed harder than the bad one",desc:"Would rather be caught in a lie than caught being kind; the concealment is of the softness.",example:"(paid the fine for the stranger. Denied it. Would have admitted to the parking.)",intensity:4,rarity:"signature",pol:{warm:1,ego:-1},conceptFamily:"contradiction-concealed-kindness",behaviorFunction:"protect",frequency:2,visibility:2,persistence:4,narrativeSalience:4,reviewStatus:"reviewed"},

// ================================================================ ROLE BY CONTEXT (draws one of each)
// ---- Among Peers
{id:170293,section:"Role by Context",category:"Among Peers",trait:"The one who books the table",desc:"Among equals, the organiser by default — dates, venues, the group message — without ever being asked or thanked.",example:"(the plan exists because they made it. It always does.)",intensity:3,rarity:"common",pol:{disc:1,agr:1},conceptFamily:"peer-organiser",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["peer"]},
{id:170294,section:"Role by Context",category:"Among Peers",trait:"The last to speak, the one they wait for",desc:"Among friends and colleagues, says little until the end — and the group holds the decision until they have.",example:"(the debate goes round. Then everyone looks at the quiet one. 'Well?')",intensity:4,rarity:"distinctive",pol:{asrt:-1,ego:1},conceptFamily:"peer-oracle",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["peer"]},
{id:170295,section:"Role by Context",category:"Among Peers",trait:"The joker among equals",desc:"With peers, the pressure valve — never the leader, never serious, always the one who makes the plan bearable.",example:"(the meeting is dire. One line from the corner. The meeting survives.)",intensity:3,rarity:"common",pol:{pos:1,warm:1},conceptFamily:"peer-joker",behaviorFunction:"soothe",reviewStatus:"reviewed",conditions:["peer"]},
{id:170296,section:"Role by Context",category:"Among Peers",trait:"The rival, affectionately",desc:"Among equals, competes with everyone about everything, and it is understood as a form of love.",example:"Beat you. — It's not a race. — Beat you though.",intensity:3,rarity:"uncommon",pol:{asrt:1,warm:1},conceptFamily:"peer-rival",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["peer"]},
{id:170297,section:"Role by Context",category:"Among Peers",trait:"Fades into the group",desc:"With peers, deliberately becomes one of the crowd — no lead, no dissent, no distinct voice — and is content there.",example:"(agreeable, present, unremarkable, glad of it)",intensity:2,rarity:"common",pol:{agr:1,ego:-1},conceptFamily:"peer-blend",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["peer"]},
{id:170298,section:"Role by Context",category:"Among Peers",trait:"The one who says what everyone's thinking",desc:"Among equals, the designated blurter — voices the group's unsaid objection and takes the heat for it.",example:"(everyone's thinking it. One person says it. That person, every time.)",intensity:4,rarity:"uncommon",pol:{hon:1,asrt:1},conceptFamily:"peer-blurter",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["peer"]},
{id:170299,section:"Role by Context",category:"Among Peers",trait:"Keeps the peace between friends",desc:"Among equals, the one who notices the friction first and moves to smooth it, quietly, before it's a thing.",example:"(changes the subject just before the two of them start. Nobody notices. That's the job.)",intensity:3,rarity:"common",pol:{agr:1,warm:1},conceptFamily:"peer-peacemaker",behaviorFunction:"soothe",reviewStatus:"reviewed",conditions:["peer"]},
{id:170300,section:"Role by Context",category:"Among Peers",trait:"Holds the group's memory",desc:"The one who remembers the story, the date, the old joke — the archive the friendship runs on.",example:"No, it was 2011, it was the OTHER pub, you had the green coat.",intensity:3,rarity:"uncommon",pol:{warm:1,cur:1},conceptFamily:"peer-archivist",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["peer"]},
{id:170301,section:"Role by Context",category:"Among Peers",trait:"The absent friend, always welcome",desc:"Rarely turns up; when they do, the group reorganises with pleasure around them, and they know it.",example:"(missed six of the last eight. Arrived at the ninth to a cheer.)",intensity:3,rarity:"distinctive",pol:{warm:1,disc:-1},conceptFamily:"peer-absent",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["peer"]},
{id:170302,section:"Role by Context",category:"Among Peers",trait:"Leads among equals, quietly resented",desc:"Takes charge of the peer group because someone must, and pays for it in small mutinies.",example:"(made the decision. Got the eye-roll. Made the next one anyway.)",intensity:4,rarity:"uncommon",pol:{asrt:1,agr:-1},conceptFamily:"peer-leader",behaviorFunction:"control",reviewStatus:"reviewed",conditions:["peer"]},
{id:170303,section:"Role by Context",category:"Among Peers",trait:"The confidant, never the confider",desc:"Everyone in the group tells them everything; they have never once told the group anything.",example:"(knows every secret at the table. Has none at the table.)",intensity:3,rarity:"distinctive",pol:{emo:-1,warm:1},conceptFamily:"peer-confidant",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["peer"]},
{id:170304,section:"Role by Context",category:"Among Peers",trait:"Skeptic of the group's plans, joins anyway",desc:"Voices every doubt about the scheme, is outvoted, and is first in the van.",example:"This is a terrible idea. — Coming? — Obviously.",intensity:3,rarity:"common",pol:{agr:1,pos:-1},conceptFamily:"peer-skeptic",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["peer"]},

// ---- Under Authority
{id:170305,section:"Role by Context",category:"Under Authority",trait:"Model employee, private mutineer",desc:"Under a boss: compliant, punctual, praised — and running an unofficial, quiet campaign of small corrections.",example:"Yes, absolutely. — (does it the right way instead, unnoticed)",intensity:3,rarity:"common",pol:{agr:1,rebel:1},conceptFamily:"authority-quiet-mutineer",behaviorFunction:"control",reviewStatus:"reviewed",conditions:["authority"]},
{id:170306,section:"Role by Context",category:"Under Authority",trait:"Argues with the boss, does the job",desc:"Contests every instruction aloud, on principle, and then carries it out exactly.",example:"It won't work. — Do it anyway. — Fine. (does it perfectly. It works.)",intensity:3,rarity:"uncommon",pol:{rebel:1,disc:1},conceptFamily:"authority-arguer",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["authority"]},
{id:170307,section:"Role by Context",category:"Under Authority",trait:"Goes silent in front of rank",desc:"Fluent among equals; in the presence of authority, monosyllabic and small.",example:"(the whole speech ready. The manager walks in. 'Fine, thanks.')",intensity:3,rarity:"common",pol:{asrt:-1,ego:-1},conceptFamily:"authority-silent",behaviorFunction:"avoid",reviewStatus:"reviewed",conditions:["authority"]},
{id:170308,section:"Role by Context",category:"Under Authority",trait:"Manages the manager",desc:"Under authority, becomes the fixer — anticipates, steers, protects the boss from their own decisions.",example:"(the boss thinks it was their idea. It's been theirs for a year.)",intensity:4,rarity:"distinctive",pol:{intel:1,disc:1},conceptFamily:"authority-manager-manager",behaviorFunction:"control",reviewStatus:"reviewed",conditions:["authority"]},
{id:170309,section:"Role by Context",category:"Under Authority",trait:"Courteous to the uniform, cold to the wearer",desc:"Respects the office scrupulously and makes clear, in every register available, that the respect stops there.",example:"Yes, sir. (the 'sir' has edges)",intensity:3,rarity:"uncommon",pol:{man:1,warm:-1},conceptFamily:"authority-office-not-person",behaviorFunction:"protect",reviewStatus:"reviewed",conditions:["authority"]},
{id:170310,section:"Role by Context",category:"Under Authority",trait:"Teacher's pet, unashamed",desc:"Under authority, seeks and enjoys approval openly, and is good enough to earn it.",example:"(front row. Hand up. Delivers. Doesn't care who's rolling their eyes.)",intensity:3,rarity:"common",pol:{agr:1,ego:1},conceptFamily:"authority-pet",behaviorFunction:"perform",reviewStatus:"reviewed",conditions:["authority"]},
{id:170311,section:"Role by Context",category:"Under Authority",trait:"Won't be managed, can be asked",desc:"Any instruction produces resistance; the identical thing framed as a request produces excellence.",example:"Do this. — No. — Could you? — Course. (already done.)",intensity:3,rarity:"distinctive",pol:{rebel:1,agr:1},conceptFamily:"authority-ask-not-tell",behaviorFunction:"control",reviewStatus:"reviewed",conditions:["authority"]},
{id:170312,section:"Role by Context",category:"Under Authority",trait:"Reports upward, honestly, to their cost",desc:"Under authority, the one who tells the boss the truth the boss doesn't want, and is repeatedly punished for it.",example:"It's not on track. — Everyone else says it is. — Everyone else wants to keep their job. It's not on track.",intensity:4,rarity:"uncommon",pol:{hon:1,asrt:1},conceptFamily:"authority-truth-teller",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["authority"]},
{id:170313,section:"Role by Context",category:"Under Authority",trait:"Invisible to the chain of command",desc:"Under any hierarchy, becomes unnoticeable — never praised, never blamed, never quite sure who they report to.",example:"(five years. The director has never learned their name. This suits everyone.)",intensity:2,rarity:"common",pol:{ego:-1,asrt:-1},conceptFamily:"authority-invisible",behaviorFunction:"avoid",reviewStatus:"reviewed",conditions:["authority"]},
{id:170314,section:"Role by Context",category:"Under Authority",trait:"Loyal to whoever's in charge today",desc:"Serves the current boss completely and the next one just as completely; the loyalty is to the chair.",example:"(three regimes. Indispensable to all of them. Missed by none.)",intensity:3,rarity:"uncommon",pol:{agr:1,hon:-1},conceptFamily:"authority-chair-loyal",behaviorFunction:"protect",reviewStatus:"reviewed",conditions:["authority"]},
{id:170315,section:"Role by Context",category:"Under Authority",trait:"The union rep, formal or not",desc:"Under authority, becomes the voice of everyone below it — whether or not anyone appointed them.",example:"(the boss says something unfair. Every head turns to one person. That person stands.)",intensity:4,rarity:"distinctive",pol:{asrt:1,agr:1},conceptFamily:"authority-rep",behaviorFunction:"protect",reviewStatus:"reviewed",conditions:["authority"]},
{id:170316,section:"Role by Context",category:"Under Authority",trait:"Charms the boss, resents the charm",desc:"Under rank, deploys warmth and deference expertly and despises themselves a little for how well it works.",example:"(laughed at the joke. Hated the laugh. Got the project.)",intensity:3,rarity:"common",pol:{warm:1,hon:-1},conceptFamily:"authority-charmer",behaviorFunction:"perform",reviewStatus:"reviewed",conditions:["authority"]},

// ---- With Dependents
{id:170317,section:"Role by Context",category:"With Dependents",trait:"The soft one, secretly",desc:"With anyone who depends on them — a child, a patient, a junior — the sternness goes and something else appears that no peer has seen.",example:"(the foreman nobody crosses. Reading 'The Gruffalo' in a voice. Doing the voices.)",intensity:3,rarity:"common",pol:{warm:1},conceptFamily:"dependent-soft",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170318,section:"Role by Context",category:"With Dependents",trait:"Sergeant to the small",desc:"With dependents, becomes brisk, rule-bound and loud — a discipline they apply to nobody their own size.",example:"(a pushover with adults. Bedtime is a military operation.)",intensity:3,rarity:"common",pol:{disc:1,asrt:1},conceptFamily:"dependent-sergeant",behaviorFunction:"control",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170319,section:"Role by Context",category:"With Dependents",trait:"Teaches by letting them fail",desc:"With those in their care, stands back and lets the small disaster happen, deliberately, and is there afterwards.",example:"(watched the tower fall. Didn't catch it. Sat down beside the crying and started again.)",intensity:3,rarity:"distinctive",pol:{disc:1,warm:1},conceptFamily:"dependent-let-fail",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170320,section:"Role by Context",category:"With Dependents",trait:"Can't say no to them",desc:"Firm with the world; the person who relies on them has never heard the word.",example:"(said no to the council, the bank and the vicar this week. Bought the pony.)",intensity:3,rarity:"common",pol:{warm:1,disc:-1},conceptFamily:"dependent-cant-refuse",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170321,section:"Role by Context",category:"With Dependents",trait:"Delegates their own childhood",desc:"With dependents, gives exactly what they were denied — the lessons, the trips, the words — with visible urgency.",example:"(never had a bike. The child has three.)",intensity:3,rarity:"uncommon",pol:{warm:1,emo:1},conceptFamily:"dependent-redress",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170322,section:"Role by Context",category:"With Dependents",trait:"Distant provider",desc:"With those who rely on them, everything is supplied and nothing is shared; love is a full fridge and a closed door.",example:"(the fees are paid. The calls are short. The fridge is always full.)",intensity:3,rarity:"uncommon",pol:{emo:-1,disc:1},conceptFamily:"dependent-provider",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170323,section:"Role by Context",category:"With Dependents",trait:"Becomes the child's age",desc:"With small people, drops entirely into their world — the floor, the game, the nonsense — and forgets to be an adult.",example:"(an hour on the carpet, fully in the game, late for everything)",intensity:3,rarity:"common",pol:{warm:1,pos:1},conceptFamily:"dependent-playmate",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170324,section:"Role by Context",category:"With Dependents",trait:"Anxious guardian",desc:"With anyone in their care, every risk is visible and every outing is a threat assessment.",example:"(the school trip form has questions on it. Many questions. In two colours.)",intensity:3,rarity:"common",pol:{mood:-1,disc:1},conceptFamily:"dependent-anxious",behaviorFunction:"protect",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170325,section:"Role by Context",category:"With Dependents",trait:"Confides in the child",desc:"Treats the dependent as a peer — tells them the money worries, the marriage, the fear — long before they should.",example:"(the nine-year-old knows about the mortgage. The nine-year-old has opinions.)",intensity:4,rarity:"distinctive",pol:{emo:1,disc:-1},conceptFamily:"dependent-confides",behaviorFunction:"connect",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170326,section:"Role by Context",category:"With Dependents",trait:"Steady hand, no fuss",desc:"With those who rely on them, an unhurried calm that makes any crisis feel managed — the voice everyone wants in the room.",example:"Right. Well. Let's have a look. (and somehow it's going to be all right)",intensity:4,rarity:"distinctive",pol:{disc:1,emo:-1},conceptFamily:"dependent-steady",behaviorFunction:"soothe",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170327,section:"Role by Context",category:"With Dependents",trait:"Expects too much, means it kindly",desc:"With dependents, sets standards no child could meet, out of a fierce belief in what they could be.",example:"You can do better than that. — I got ninety. — You can do better than ninety.",intensity:3,rarity:"uncommon",pol:{disc:1,warm:1},conceptFamily:"dependent-demanding",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["dependent"]},
{id:170328,section:"Role by Context",category:"With Dependents",trait:"Lets them lead",desc:"With those in their care, hands over the map, the choice, the decision — earlier than anyone else would.",example:"Which way? — You pick. — I'm seven. — You pick.",intensity:3,rarity:"distinctive",pol:{ego:1,agr:1},conceptFamily:"dependent-hand-over",behaviorFunction:"provide",reviewStatus:"reviewed",conditions:["dependent"]},
];

TRAITS.push(...TRAITS_LIFE);
